const MAIN_QUESTS=[
  {"ch":"Prolog","name":"Dead of Night","quests":[{"q":"Unfamiliar Lands","trigger":"Automatisch zu Spielbeginn; startet bei der Cabin in den Hills of No Return (Hernand), nachdem die Black Bears das Lager der Greymanes überfallen haben","prereq":"Keine (erste Quest des Spiels)","reward":"—","miss":false,"tip":"Reine Dialog-/Erkundungsquest: Mit Oongka, Marius (bei den Pferden) und Ross (an einem Baum, südlich bei den Gräbern) sprechen, dann die Cabin betreten – dort folgt die Nachricht, dass Anführer Jian gefallen ist. Das Gespräch mit Oongka ist laut PowerPyx optional.","conf":"high"},{"q":"In Ashes","trigger":"Automatisch nach Abschluss von 'Unfamiliar Lands' (Hills of No Return, Hernand)","prereq":"Unfamiliar Lands","reward":"—","miss":false,"tip":"Kampf-Tutorial: Erst 5 Gegner besiegen, dann den drei markierten Verbündeten Naira (Norden, 8 Gegner), Oongka (Osten) und Yann (Westen) helfen; Bogenschützen zuerst ausschalten. Danach Bosskampf gegen Myurdin – der Ausgang ist egal (laut PowerPyx folgt dieselbe Cutscene), Kliff verliert per Story und landet im Fluss.","conf":"high"},{"q":"Realm of Uncertainty","trigger":"Automatisch nach der Niederlage gegen Myurdin; spielt im 'Corridor of the Void' im Abyss","prereq":"In Ashes","reward":"Skill 'Blinding Flash' (laut Fextralife; PowerPyx listet keine Belohnung)","miss":false,"tip":"Lineares Bewegungs-Tutorial (Springen, Klettern, Ducken). Blinding Flash (L1+R1) auf die Lichtkugel über der Tür reflektieren, um sie zu öffnen; danach bewegliche Plattformen und mit der Laterne durch den dunklen Korridor. Am Ende auf das Artefakt im Hof treten – Cutscene beendet die Quest.","conf":"high"},{"q":"New Journey","trigger":"Automatisch nach 'Realm of Uncertainty'; beginnt an den Three Saints' Falls (Hernand), wo Kliff auf Sebastian trifft","prereq":"Realm of Uncertainty","reward":"Standard Inventory Expansion Tool x1, Oats x10, Blackberry x5 (PowerPyx + game8; Fextralife nennt zusätzlich Medium Bag)","miss":false,"tip":"Sebastian folgen, unterwegs zwei Bleed Bandits abwehren (getimte Blocks), dann zu Pferd weiter nach Hernand. Optional: Am Fluss das Angeln lernen; auf dem Weg liegen laut Fextralife zwei Sealed Abyss Artifacts (Vogelhaus hinter der Brücke, kleines Denkmal links der Straße).","conf":"high"}],"boss":null,"warn":null,"unlock":null},
  {"ch":"1","name":"The First Encounter","quests":[{"q":"Where Rumors Gather","trigger":"Automatisch nach 'New Journey'; Ziel ist die Hernand Tavern in der City of Hernand","prereq":"New Journey","reward":"Münzen (laut PowerPyx 'Coins'; game8 listet für das Sub-Chapter u.a. Silver x1)","miss":false,"tip":"Zur Taverne im Süden und den Soldaten am Tisch zum Armdrücken herausfordern: Button mashen, bis die Leiste rot gefüllt ist, zwischendurch Quick-Time-Fenster treffen.","conf":"high"},{"q":"Mysterious Man","trigger":"Automatisch nach 'Where Rumors Gather': Beim Verlassen der Taverne liegt ein alter Bettler (der verkleidete Alustin) auf dem Abwassergitter im Vorhof","prereq":"Where Rumors Gather","reward":"Shabby Wooden Key (Questgegenstand); Zusatzbelohnung quellenabhängig: Fextralife Medium Bag, PowerPyx Standard Inventory Expansion Tool","miss":false,"tip":"Dem Bettler eine Münze geben – er übergibt den Shabby Wooden Key und verschwindet. Schaltet drei parallel spielbare Folgequests frei (True Wisdom in Kindness, Actions Speak Louder Than Words, Heart Beyond Borders).","conf":"medium"},{"q":"True Wisdom in Kindness","trigger":"Nach 'Mysterious Man': Seltsame Geräusche aus dem Eisengitter untersuchen, auf dem der Bettler lag (Falltür neben der Taverne, Abstieg in die Hernand Sewers)","prereq":"Mysterious Man","reward":"Sealed Letter, Engraved Key (Questgegenstände; laut Fextralife)","miss":false,"tip":"In der Kanalisation vorsichtig über den brüchigen Boden springen (Ziel-Sprung: L1 halten + Sprungtaste). Am Ende die gefesselte Frau (White Crow, als Adlige verkleidet) befreien; danach verwandelt sich der Shabby Wooden Key in den Engraved Key.","conf":"high"},{"q":"Actions Speak Louder Than Words","trigger":"Nach 'Mysterious Man': Südöstlich der Taverne zur Muckroot Ranch gehen und mit den Dorfbewohnern Arlan und Lauren sprechen","prereq":"Mysterious Man","reward":"Lentils x10, Apple x5, Hernandian Attire, Medium Bag, +100 Hernandian Contribution (laut Fextralife; game8 bestätigt Lentils/Apple)","miss":false,"tip":"Schornstein-Reinigung: Besen neben der Haustür nehmen, über die Kisten aufs Dach, auf dem Schornstein mit L1 zielen und reinigen. Nicht verpassen: Hinter dem Haus liegt eine Palmar Pill. Die Hernandian Attire wird später für 'Mystical Key' gebraucht!","conf":"medium"},{"q":"Heart Beyond Borders","trigger":"Nach 'Mysterious Man': Westlich der Taverne das Kind mit grüner Kapuze (Rulupee) in einem Hof ansprechen","prereq":"Mysterious Man","reward":"Shai's Pendant (laut Fextralife; wird nach der Cutscene fallen gelassen und muss aufgehoben werden)","miss":false,"tip":"Per Freerunning aufs Dach klettern und Rulupees Katze Jiji schnappen, dann zurückbringen; den Anhänger aufheben. Nicht verpassen (PowerPyx): Im Turm über dem Katzen-Dach die Glocke läuten – lüftet den Kartennebel in Hernand (eine von 8 Glocken). Hinweis: Quellen schreiben 'Heart Beyond Borders' (Singular).","conf":"medium"},{"q":"Mystical Key","trigger":"Automatisch, sobald die drei Kindness-Quests abgeschlossen sind: Den Engraved Key im Inventar untersuchen – Ziel ist Hernand Castle","prereq":"True Wisdom in Kindness + Actions Speak Louder Than Words + Heart Beyond Borders","reward":"—","miss":false,"tip":"Wichtig: Vor dem Schlosstor die Hernandian Attire (lila Mantel) anlegen, sonst kommt man nicht an den Wachen vorbei. Im Schloss zur Alchemist's Chamber (erste Tür links im großen Korridor), die leuchtende Truhe öffnen (Faded Abyss Artifact) und durch das Abyss Gate treten.","conf":"high"},{"q":"Polar Opposites","trigger":"Automatisch nach 'Mystical Key': Durch das Abyss Gate wird Kliff ins Axiom Archive im Abyss versetzt","prereq":"Mystical Key","reward":"Skill 'Axiom Force' (laut Fextralife)","miss":false,"tip":"Erst den Abyss Nexus aktivieren (Schnellreise), dann das Bodenplatten-Puzzle: Mit der Laterne (L1) die gelben Leitungslinien sichtbar machen, mit Axiom Force zwei Scheiben so drehen, dass Energie durch beide fließt. Tipp: Während Axiom Force sind die Linien unsichtbar – Positionen vorher merken.","conf":"high"},{"q":"Abyss Without Balance","trigger":"Automatisch nach 'Polar Opposites': Alustin führt Kliff zum Skybridge-Gate im Axiom Archive","prereq":"Polar Opposites","reward":"Skill 'Force Palm' + 2 Abyss Artifacts (laut Fextralife; werden im Questverlauf aufgesammelt)","miss":false,"tip":"Längere Abyss-Puzzle-Sequenz: Ausrichtungs-Totems mit Axiom Force drehen (bis zum hohen Ton), über bewegliche Plattformen zum Abyss-Herz, Energiekerne auf Podeste setzen, per 'Watch and Learn' die Force Palm lernen. Das letzte Artefakt liegt oberhalb der runden Wand bei der Stromaktivierung – nicht übersehen.","conf":"high"},{"q":"Woman in White","trigger":"Automatisch nach 'Abyss Without Balance': Am Ethereal Pathway vorwärtsgehen, Cutscene mit der Frau in Weiß (White Crow)","prereq":"Abyss Without Balance","reward":"Faded Abyss Artifact x1, Palmar Pill x1 (PowerPyx + game8); dazu Flugfähigkeit (Schwingen) und laut Fextralife Shining Shai Pendant","miss":false,"tip":"Kurze Story-Quest: White Crow verleiht Kliff die Flugfähigkeit (in der Luft Sprungtaste = Schwingen ausfahren; Fliegen verbraucht Ausdauer). Nach QTE vom Ethereal Pathway abspringen und zurück zur City of Hernand gleiten – Ende von Kapitel 1.","conf":"high"}],"boss":null,"warn":null,"unlock":null},
  {"ch":"2","name":"Golden Greed","quests":[{"q":"Where the Light Leads","trigger":"Automatisch nach Kapitel 1 ('Woman in White'): Das grüne Pendant leuchtet und weist per Lichtstrahl zum Lioncrest Watchtower südwestlich der City of Hernand","prereq":"Woman in White (Kapitel 1)","reward":"Arrow x10","miss":false,"tip":"Rund 10 Banditen am Lioncrest Watchtower besiegen (Bogenschützen zuerst). Die Ranken am Turmeingang mit einem Feuerpfeil abbrennen, den Turm besteigen; oben im Studierzimmer den goldenen Helm (Visione) untersuchen.","conf":"high"},{"q":"Memory Fragment","trigger":"Automatisch an der Turmspitze des Lioncrest Watchtower nach 'Where the Light Leads'","prereq":"Where the Light Leads","reward":"—","miss":false,"tip":"Den goldenen Visione-Helm aufheben (wird automatisch ausgerüstet) und Delysias Erinnerung 'Visione' über das Menü lesen – so liest man auch künftig am schnellsten Erinnerungsfragmente.","conf":"high"},{"q":"Reunion","trigger":"Rulupee (die Shai mit der Katze) erscheint auf der Mauer über dem Torbogen beim Lioncrest Watchtower und bittet Kliff, ihrer Katze Jiji zu folgen","prereq":"Memory Fragment","reward":"Medium Bag/Standard Inventory Expansion Tool x1 (Quellen abweichend), Palmar Pill x1; Skills: Nature's Grasp, Focus","miss":false,"tip":"Der Katze zu den Klippenruinen folgen; dort Nature's Grasp und Focus lernen. In der Höhle drei Wandplattformen per Force Palm in der Reihenfolge Mitte → links → rechts aktivieren; das Abyss Artifact (Skillpunkt) mitnehmen, bevor man mit dem Kind spricht.","conf":"high"},{"q":"For Honor","trigger":"Hernand Square: Eine Rittergruppe des Order of Light redet über die Greymanes; Kliff stellt Matthias zum Duell","prereq":"Reunion","reward":"—","miss":false,"tip":"Duell gegen Matthias in zwei Phasen (blaue, dann rote HP-Leiste); klar telegrafierte Angriffe. Beim Pump Kick (Arme sinken, dann Sturm) seitlich ausweichen – der Skill 'Pump Kick' ist hier per Watch and Learn lernbar (im Kampf beobachten, sonst verpassbar).","conf":"high"},{"q":"Awestruck","trigger":"Automatisch nach dem Matthias-Duell in Hernand Square","prereq":"For Honor","reward":"—","miss":false,"tip":"Sehr kurze Quest: Barden Middler (Ritterkleidung ohne Helm) in der Menge finden und ansprechen, Cutscene beendet die Quest.","conf":"high"},{"q":"Shadow Cast Over the River","trigger":"Ab Hernand Square dem Questmarker zur Springtide Mill folgen","prereq":"Awestruck","reward":"Standard Inventory Expansion Tool x1, Toasted Grains x10, Grilled Fruit x5","miss":false,"tip":"Alle Bleed Bandits rund um die Brücke bei Springtide Mill besiegen. Vorsicht beim berittenen Banditen: gezielt den Reiter treffen – trifft man das Pferd, gibt es ein Kopfgeld. Falls Gegner fehlen, das nahe Lager prüfen.","conf":"high"},{"q":"Where Misery Gathers","trigger":"Anschlagtafel (Notice Board) bei Springtide Mill untersuchen","prereq":"Shadow Cast Over the River","reward":"—","miss":false,"tip":"Vier Aushänge abnehmen und lesen: 'Missing Cows', 'Horn Thief', 'Missing Wooly', 'Strange Noises from the Cave' – schaltet vier Folgequests frei (beliebige Reihenfolge).","conf":"high"},{"q":"Trial After Trial","trigger":"Aushang 'Missing Cows': den verzweifelten Bauern Bremer auf seinem Hof nahe Springtide Mill ansprechen","prereq":"Where Misery Gathers","reward":"Münzen, Standard Inventory Expansion Tool x1, Thin Hide x5","miss":false,"tip":"Mit Bremer sprechen, die Kräuterkundlerin als Zeugin bezahlen und ihr zu Pferd zum Banditenlager folgen. Lager säubern, per Laterne das Erinnerungsfragment zu den Rindern lesen, zurück zu Bremer. Im Lager: Amboss + Schleifstein für Reparatur/Buff.","conf":"high"},{"q":"The Man Trapped in the Mire","trigger":"Aushang 'Horn Thief': den bestohlenen Rancher Ibano beim Marker nahe Springtide Mill ansprechen","prereq":"Where Misery Gathers","reward":"Münzen, Standard Inventory Expansion Tool x1, Cloth Pieces x5","miss":false,"tip":"Östlich das kleine Banditenlager ausheben, per Laterne das Erinnerungsfragment zur 'Hornless Goat' lesen und das Mysterious Elixir bei den Felsen aufheben, dann zu Ibano zurück.","conf":"high"},{"q":"Missing Companion","trigger":"Aushang 'Missing Wooly': das weinende Kind William bei Bloomwood Ranch ansprechen, das sein Schaf Wooly vermisst","prereq":"Where Misery Gathers","reward":"Standard Inventory Expansion Tool x1, Fleece x5","miss":false,"tip":"Zwei Zeugengruppen südlich der Ranch befragen, das Banditenlager jenseits des Flusses räumen, Wooly aus dem Pferch holen und das Schaf (zu Pferd) zurück zu William bringen.","conf":"high"},{"q":"Secrets Hidden in the Dark","trigger":"Aushang 'Strange Noises from the Cave': bei Bloomwood Ranch wird der Betrunkene Boris von zwei Männern bedrängt – ansprechen und ihm folgen","prereq":"Where Misery Gathers","reward":"Medium Bag/Standard Inventory Expansion Tool x1, Grilled Meat x5, Grilled Fruit x5; laut Fextralife +100 Hernandian Contribution","miss":false,"tip":"Boris zum Specter's Hideout (Nas Riverside) folgen, Banditen am Eingang besiegen. Verpassbar: Skill 'Dropkick' per Watch and Learn von einem Banditen vor der Höhle + Palmar Pill in der Höhle. Hinten per Laterne die Erinnerung 'Lair of the Animal Thieves' lesen, danach die Wachen im Nordosten ansprechen.","conf":"high"},{"q":"The Dark Veil","trigger":"Zum Goldleaf Tradepost / Unicorn Cliff südöstlich der City of Hernand reisen und den Händler Shakatu am Markt ansprechen","prereq":"Alle vier Notice-Board-Quests (Trial After Trial, The Man Trapped in the Mire, Missing Companion, Secrets Hidden in the Dark)","reward":"—","miss":false,"tip":"Sehr kurze reine Dialogquest: Mit Shakatu sprechen, Cutscene über die Goldleaf Merchant Guild ansehen.","conf":"high"},{"q":"The Flames of Greed","trigger":"Eine weinende Nonne ruft beim Goldleaf Tradepost um Hilfe; sie bittet darum, ihren Heiler zu retten","prereq":"The Dark Veil","reward":"Münzen, Abyss Artifact x1","miss":false,"tip":"Zum brennenden Haus des Heilers in Windland Heights reiten. 2-Minuten-Timer: Mit Nature's Grasp den Baumstamm vor der Tür wegräumen, Marten im Haus (hinten rechts oben) aufnehmen und nach draußen tragen.","conf":"high"},{"q":"Kidnapped Healer","trigger":"Dem Questmarker zum Lagerplatz in den Hernand Highlands folgen","prereq":"The Flames of Greed","reward":"Standard Inventory Expansion Tool x1","miss":false,"tip":"Den Entführer am Lager besiegen und den Heiler Hubert losbinden – kurze Quest.","conf":"high"},{"q":"Rebellion or Revolution","trigger":"Automatisch nach 'Kidnapped Healer' in den Hernand Highlands; zum Marker gehen und Shakatu treffen","prereq":"Kidnapped Healer","reward":"—","miss":false,"tip":"Beim Treffen mit Shakatu greifen Gegner an – alle besiegen, dann Shakatu folgen und mit ihm sprechen. Hinweis: korrekter Questname laut allen Quellen 'Rebellion or Revolution' (im Wiki stand vorher 'of').","conf":"high"},{"q":"Cheers Echoing From the Edge","trigger":"Nach 'Rebellion or Revolution' zum Goldleaf Guildhouse in Unicorn Cliff; vor dem Gebäude greifen Wachen an, danach folgt der Kapitel-Boss","prereq":"Rebellion or Revolution","reward":"Sword of the Lord x1, Iron Ore x7, Copper Ore x2; laut Fextralife zusätzlich Seal of Greed - Goldleaf Merchant Guild und +500 Hernandian Contribution","miss":false,"tip":"Kapitel-Boss Kailok the Hornsplitter (sehr schnell): Defensiv spielen, parieren/perfekt kontern, nach der Parade 1–2 Treffer, roten Glint-Angriff mit Force Palm kontern (Stagger). Dem Wind Slash seitlich ausweichen, bei blauem Super-Armor-Glühen nicht angreifen; 'Evasive Roll' per Watch and Learn lernbar. Vorher beim Schmied aufrüsten und ca. 40 Grilled Meat mitnehmen.","conf":"high"}],"boss":"Kailok the Hornsplitter","warn":null,"unlock":null},
  {"ch":"3","name":"Howling Hill","quests":[{"q":"Old Friend","trigger":"In den Hintergassen der City of Hernand (hinter dem Gasthaus) eine Menschengruppe ansprechen; Cutscene mit Marius","prereq":"Cheers Echoing From the Edge (Ende Kapitel 2)","reward":"—","miss":false,"tip":"Reine Story-Quest: Gasse aufsuchen, Cutscene ansehen (Kliff trifft Marius wieder). Keine Kämpfe.","conf":"high"},{"q":"First Step to Rebuilding","trigger":"Bei Oakenshield Manor (Anwesen des Marquis Serkis) den Riesen vor dem Eingang ansprechen","prereq":"Old Friend","reward":"Camp Howling Hill, Camp-Ressourcen, Damiane (spielbare Gefährtin), Reittier Brianto, Allianzen mit House Serkis + House Celeste","miss":false,"tip":"Nach dem Gespräch mit Marquis Serkis einem Soldaten erst zu Fuß, dann zu Pferd nach Howling Hill folgen. Im Lagerzentrum Marshal Middler treffen; Damiane schließt sich als Comrade an.","conf":"high"},{"q":"A Fresh Start","trigger":"Automatisch im neuen Camp auf Howling Hill","prereq":"First Step to Rebuilding","reward":"Iron Ore x5","miss":false,"tip":"Vier Aufbau-Aufgaben in beliebiger Reihenfolge: drei Säcke tragen, vier Zeltpflöcke einschlagen (je 3 Schläge), drei Felsen mit der Spitzhacke zerschlagen + Wagen ins Zelt schieben, Banner mit Nature's Grasp in die Halterung heben.","conf":"high"},{"q":"Reward for Their Sweat","trigger":"Automatisch im Camp (Missionsmarker am Kochtopf)","prereq":"A Fresh Start","reward":"Clear Soup x10","miss":false,"tip":"Rezept vom Hocker neben dem Kochtopf nehmen und lesen; 'Modest Clear Soup' kochen (je x1 Tough Meat, Barley, Water – Zutaten auf demselben Hocker). Mindestens 2 Portionen und das Festmahl am Tisch servieren (ggf. zu Kliff wechseln).","conf":"high"},{"q":"Return of the Comrade","trigger":"Am Scrapfold (Hernand): Marius zwischen Bettlern aufsuchen","prereq":"Reward for Their Sweat","reward":"—","miss":false,"tip":"Marius ansprechen, aufs Pferd steigen, warten bis er aufsitzt, zurück zum Camp eskortieren. Achtung: Kommen Bettler zu nahe, kann das Münzen kosten.","conf":"high"},{"q":"Familiar Curses","trigger":"Bei St. Halssius's House of Healing (Hernand)","prereq":"Return of the Comrade","reward":"St.-Halssius-Priester-Outfit (Attire, Cloak, Footwear, Hat; an Beschaffung der Verkleidung geknüpft)","miss":false,"tip":"Drei Wege ins Haus: schleichen, Besucherpass der Church of Hernand kaufen oder Halssius-Outfit (10 Silber) beim Händler nahe der Brücke. Im Südflügel des 2. Stocks Yann stellen, über die Dächer bis zum Pywell Wagon jagen, zum Nas River Fishing Dock fahren. Wachen meiden – Zivilisten dürfen einen sehen.","conf":"medium"},{"q":"Return","trigger":"Greymane-Campingplatz am Nas River Fishing Dock; Gespräch mit Marius (dort trifft man Duane)","prereq":"Familiar Curses","reward":"—","miss":false,"tip":"Nur ein Gespräch. WICHTIG (PowerPyx): Vorbereiten – ca. 50 Grilled Meat kochen, Plattenrüstung kaufen und beim Schmied aufwerten: der kommende Kapitel-Boss ist isoliert und sehr schwer.","conf":"high"},{"q":"Traces in the Manor","trigger":"Glenbright Manor (Grace Estate, südlich des Markers); Cutscene bei Ankunft","prereq":"Return","reward":"—","miss":false,"tip":"Bei Ankunft greifen fünf Wachen an. Anwesen durchsuchen, im Obergeschoss im Eckzimmer den verwundeten Diener ansprechen (laut game8 erhält man den Iron Door Key). Folgequest startet im selben Raum.","conf":"high"},{"q":"Nonhuman","trigger":"Automatisch in Glenbright Manor nach 'Traces in the Manor' (nach Diener-Gespräch und Visione-Erinnerung 'Grace Manor')","prereq":"Traces in the Manor","reward":"—","miss":false,"tip":"Tracking-Mechanik: Laterne (L1) auf das offene Fenster richten und der gelben Spur des Reed Devil bis zur Hütte bei Reedfield Graves folgen. Kämpfe unterwegs sind laut game8 vermeidbar.","conf":"high"},{"q":"Seed of Unease","trigger":"Automatisch nach Cutscene in der Hütte bei Reedfield Graves","prereq":"Nonhuman","reward":"—","miss":false,"tip":"Mit der Laterne der gelben Spur durch den Canyon nach Südwesten folgen (Steel Mountains / Mountain of Frozen Souls). Der Reed Devil taucht mehrfach auf und verschwindet wieder – andere Gegner umgehen, zwischendurch heilen. Am Altar die kleine Strohpuppe untersuchen → löst den Bossfight aus.","conf":"high"},{"q":"Dance with the Devil","trigger":"Automatisch nach Untersuchen der Puppe am Altar; Bossfight gegen den Reed Devil","prereq":"Seed of Unease","reward":"Sunset Reed Cloth Gloves x1","miss":false,"tip":"Kapitel-Boss, 3 Phasen: Phase 1 eins-gegen-eins – schnelle Schwerthiebe parieren, Haltung brechen. Phase 2: unverwundbar + Klone – so schnell wie möglich alle Totems/Vogelscheuchen zerstören (Quellen: 4 bzw. 5), nicht die Klone bekämpfen. Phase 3 wie 1, aggressiver mit roten Energiewellen (seitlich wegrollen). Vorher 50–100 Grilled Meat + aufgewertete Plattenrüstung!","conf":"high"},{"q":"Hope After the Draught","trigger":"Automatisch nach dem Sieg über den Reed Devil; zurück zum Camp auf Howling Hill","prereq":"Dance with the Devil","reward":"—","miss":false,"tip":"Zurück ins Camp (Tipp: per Sky Map zur Himmelsinsel nördlich des Camps schnellreisen und hinabspringen), Hauptzelt betreten – Cutscene: Andrew erholt sich, Yann trifft ein.","conf":"high"},{"q":"Scattered Comrades","trigger":"Automatisch im Camp auf Howling Hill","prereq":"Hope After the Draught","reward":"—","miss":false,"tip":"Kurzes Gespräch mit Marius über die verstreuten Gefährten – keine Kämpfe. (Quest fehlte bisher im Wiki.)","conf":"high"},{"q":"Rumors from the Sawmill","trigger":"Nach Marius' Hinweis zum Sägewerk reisen (PowerPyx/Fextralife: Coalvale Workshop nahe Howling Hill; game8 nennt Unicorn Cliff)","prereq":"Scattered Comrades","reward":"Camp Wood x1000, Abyss Artifact x1, Fine Timber x5","miss":false,"tip":"Am Sägewerk den sitzenden Mann Luke finden, anvisieren und ansprechen, um ihn (laut game8 mit Ronald) zu rekrutieren. (Quest fehlte bisher im Wiki.)","conf":"medium"},{"q":"A Gentle Touch","trigger":"Automatisch nach der Rekrutierung; zurück zum Camp auf Howling Hill","prereq":"Rumors from the Sawmill","reward":"Camp Oats x200, Camp Coins x200, Thick Hide x6, Iron Ore x5","miss":false,"tip":"Im Camp den Schrein untersuchen, dann die Dragon-Head-Totem-Statue links davon. Den Brief 'Shakatu's Letter' (lila) aus dem Inventar öffnen und mit L1 vollständig lesen – schaltet die Camp Expansion frei. (Quest fehlte bisher im Wiki.)","conf":"high"},{"q":"Bustling Hill","trigger":"Automatisch nach Lesen des Briefs; Dispatch-Mission über die Karte starten","prereq":"A Gentle Touch","reward":"—","miss":false,"tip":"Auf der Karte (Tab 'ALL') das Howling Hill Camp öffnen, Mission 'Howling Hill Camp Expansion' wählen, Luke und Ronald entsenden. Dauer 18 Ingame-Stunden – mit Nebenquests überbrücken oder am Bett/Lagerfeuer 12 Stunden schlafen.","conf":"high"},{"q":"Greymanes Reunited","trigger":"Automatisch nach Abschluss der Camp-Expansion","prereq":"Bustling Hill","reward":"—","miss":false,"tip":"Zum markierten Bereich des erweiterten Camps zurückkehren – Cutscene mit den versammelten Gefährten. Danach beginnt Kapitel 4.","conf":"high"}],"boss":"Reed Devil","warn":null,"unlock":"Damiane (First Step to Rebuilding)"},
  {"ch":"4","name":"The Price of Knowledge","quests":[{"q":"Kilnden Workshop","trigger":"Westlich von Hernand Castle: NPC mit Visione Helmet auf einem Hügel vor einem Turm ansprechen (am schnellsten per Fast Travel zum Abyss-Punkt und Skydive)","prereq":"Greymanes Reunited (letzte Quest von Kapitel 3)","reward":"—","miss":false,"tip":"Reine Dialog-Quest: den NPC mit dem Visione Helmet (Grimnir) auf dem Hügel ansprechen. Ist er nicht anzutreffen, per Options-Taste die Zeit auf Tag vorspulen — er ist nur tagsüber verfügbar. Kein Kampf, kein Rätsel.","conf":"medium"},{"q":"Kiln Repair at the Kilnden Workshop","trigger":"Startet automatisch nach 'Kilnden Workshop' am Ancient-Generator-Turm im Hernand-Gebiet","prereq":"Kilnden Workshop","reward":"—","miss":false,"tip":"Vier Aufgaben: Am Ancient Generator die vier leuchtenden Symbole über den gelben und den hölzernen Hebel ausrichten; fünf blau leuchtende Kugeln (per Axiom Force aufspürbar) als Brennstoff in die Kiln-Öffnungen stecken; den zerlegten Kiln mit Axiom Force stapeln und per Force Palm in der Luft verbinden; beim dritten Kiln das lose Stromkabel anschließen und den Holzhebel drücken. Danach Grimnir am Generator ansprechen. Spawnt eine blaue Kugel nicht: Spiel neu starten (von PowerPyx bestätigter Bug-Fix).","conf":"high"},{"q":"The Mysterious Pot","trigger":"Kilnden Workshop (Hernand): Grimnir erneut ansprechen (nur tagsüber verfügbar; ggf. per Options-Taste warten)","prereq":"Kiln Repair at the Kilnden Workshop","reward":"Kuku Iron Pot","miss":false,"tip":"Grimnir ansprechen, dann den Hebel direkt neben ihm im Uhrzeigersinn drücken — der Boden öffnet sich. Den Kuku Pot auf der runden Steinplattform einsammeln, fertig.","conf":"high"},{"q":"The Iron Pot's Usage","trigger":"Questmarker südwestlich des Kilnden Workshop: den Zwerg Togrum ansprechen","prereq":"The Mysterious Pot","reward":"— (laut Fextralife erhält man das Quest-Item Magnetic Power Source; PowerPyx nennt keine Belohnung)","miss":false,"tip":"Nach dem Gespräch mit Togrum Axiom Force (L3) auf die Steinkugel mit der Magnetic Power Source links vom Zwerg wirken und das Objekt mit gehaltenem Dreieck/Y in den Pot einsaugen — der Kuku Iron Pot schluckt Objekte jeder Größe. Fextralife führt die Quest unter dem Namen 'The Pot's Use'.","conf":"high"},{"q":"Disturbance at the Arena","trigger":"Rückkehr zum Greymane Camp auf Howling Hill: am Hauptzelt startet automatisch ein Gespräch mit den Gefährten, danach Duane zur Arena folgen","prereq":"The Iron Pot's Usage","reward":"Schaltet das Arena-Minigame frei (laut PowerPyx); optional 1 Artifact für die 'Steel Fist'-Challenge (drei Siege in Folge ohne Niederlage)","miss":false,"tip":"30 Copper Startgeld zahlen und vor dem Kampf auf Plain Gloves wechseln (D-Pad links halten) — Waffen führen zur Disqualifikation. Drei Faustkämpfe nur mit unbewaffneten Angriffen gewinnen, gegnerische Konter mit L1/LB blocken. Der Champion-Kampf ist laut PowerPyx optional. Danach mit Duane sprechen und mit Yann zurück nach Howling Hill reiten.","conf":"high"},{"q":"Skilled in Archery","trigger":"Naira ansprechen (laut PowerPyx in einem offenen Hof südwestlich von Hernand Castle, laut Fextralife bei Capra Pasture), dann mit Duane zum Bogenschieß-Wettkampf reiten","prereq":"Disturbance at the Arena","reward":"Schaltet das Archery-Minigame frei (laut PowerPyx; Fextralife nennt stattdessen Silber/Kupfer)","miss":false,"tip":"Beim Wettkampf (laut Fextralife bei Lioncrest Manor, 80 Copper Einsatz) 10 Ziele schneller treffen als der gegnerische Hernand Guard. Das Visier mittig halten und nur kurz nach links oder rechts ziehen, wenn dort ein Ziel aufpoppt. Danach draußen mit Duane sprechen.","conf":"high"},{"q":"The Words of Alustin","trigger":"Im Süden der City of Hernand: ein Fremder rempelt Kliff absichtlich an und steckt ihm 'Alustin's Letter' zu","prereq":"Skilled in Archery","reward":"—","miss":false,"tip":"Kurze Story-Quest: in den Süden Hernands gehen, nach der Rempel-Szene das lila Alustin's Letter im Inventar öffnen und lesen (heranzoomen). Spawnt der Fremde nicht, hilft manuelles Speichern und Neuladen (PowerPyx-Tipp).","conf":"high"},{"q":"Scholastone","trigger":"In Hernand den Hehler aufsuchen ('the fence', Goblin-Händler im Obergeschoss eines Hauses; laut Fextralife Darroch im Bluemont Manor)","prereq":"The Words of Alustin","reward":"Scholastone Uniform","miss":false,"tip":"Beim Hehler die Verkleidung abholen, dann zum Marker südwestlich der Stadt reisen und den Berg mit drei Force-Palm-Sprüngen in der Luft erklimmen. Vor dem Steintor die Scholastone Uniform im Inventar anlegen und dem Mann an der Steinpyramide zu den Klippen folgen; auf dem letzten Stück Richtung Turm startet die nächste Quest automatisch. Tipp: zum Institut der Straße folgen statt zu gleiten — am Weg liegt der verpassbare Focused-Force-Palm-Punkt (siehe On the Right Path).","conf":"high"},{"q":"On the Right Path","trigger":"Scholastone Institute (Hernand): den Dekan Grundir in blau-weißer Robe auf der Brücke ansprechen","prereq":"Scholastone","reward":"—","miss":true,"tip":"Dem Dekan durchs Institut folgen, bis er einen Octavius vorstellt; verweigert er das Gespräch, die Scholastone Uniform anlegen. VERPASSBAR (laut PowerPyx & game8 die eine technische Missable des Spiels; Workaround in Kapitel 9): Auf der Anreise zum Institut liegt ca. 350 m südlich ein Beobachtungspunkt (Geist an einer auffällig gefärbten Wand), der den Skill Focused Force Palm lehrt — wer gleitet oder schnellreist, verpasst ihn. Laut TheGamer später am selben Ort nachholbar, laut space4games sonst erst automatisch in Kapitel 9.","conf":"high"},{"q":"Gate to the Otherworld","trigger":"Scholastone Institute: dem Orc-Gelehrten Octavius (blaue Robe) zuhören; laut Fextralife ggf. 24 Ingame-Stunden nach 'On the Right Path' warten","prereq":"On the Right Path","reward":"1x Abyss Artifact; laut Fextralife zusätzlich Key to the Spire of the Stars vom Dekan (von game8 bestätigt)","miss":false,"tip":"Im Untergrund nordöstlich das Luken-Rätsel lösen: erst die vier Eckknöpfe drücken (Fextralife: oben links, unten rechts, oben rechts, unten links), dann die Mitte. Vier Batterien per Axiom Force holen und mit Force Palm in die vier Pfeiler drücken, anschließend den Kern aus der blauen Kugel ziehen. Boss Tenebrum: Blinding Flash aktivieren, um die Schwachpunkte sichtbar zu machen, dann per Doppelsprung + Force Palm in der Luft attackieren; hinter Säulen Spirit regenerieren.","conf":"high"},{"q":"Spire of the Stars","trigger":"Scholastone Institute: Gespräch mit Grundir über das seltsame Phänomen am Turm nach Octavius' Verschwinden","prereq":"Gate to the Otherworld","reward":"—","miss":false,"tip":"Vom Institut nordöstlich an der Banketthalle vorbei, die Treppen durch die Höhle hinauf zum großen Steintor (Zugang über den Key to the Spire of the Stars). Im Turm drei gelbe Wände per Force Palm (R3) in den Seitenräumen aktivieren, die drei erhaltenen Würfel in die Wandsockel setzen und nach oben drücken; dann die vier Symbole durch Klettern und Hängen in die richtigen Slots schieben (ganz links nach ganz oben, zweites von links an die zweite Position usw.). Mit dem Aufzug nach oben fahren und den Abyss betreten.","conf":"high"},{"q":"Obsession and Madness","trigger":"Startet automatisch beim Betreten des Abyss-Rifts (Sanctorum of Insight) am Ende von 'Spire of the Stars'","prereq":"Spire of the Stars","reward":"+8 Contribution Levels bei der Hernandian-Fraktion (laut PowerPyx)","miss":false,"tip":"Im Abyss zuerst den Fast-Travel-/Nexus-Punkt direkt voraus aktivieren. Die hohen Säulen mit drei Force Palms in Serie beim Springen erklimmen — das Spiel erklärt diese Technik nie; Spirit per L3+R3 aufladen. Laut Fextralife lassen sich Säulen alternativ über Drehscheiben an den Turmbasen per Axiom Force versetzen. Auf der Hauptplattform über den gelb leuchtenden Bodenmechanismus springen und ihn per Force Palm in der Luft auslösen; die Cutscene (Octavius zerfällt zu Staub) beendet die Quest.","conf":"high"},{"q":"Casted Shadow","trigger":"Startet automatisch: Cutscene-Gespräch mit Dean Grundir nach 'Obsession and Madness'","prereq":"Obsession and Madness","reward":"10x Honey Tea (Consumable; laut Fextralife als Rezept)","miss":false,"tip":"Nur zwei Schritte: das Gespräch mit Grundir läuft automatisch ab, danach zurück nach Howling Hill — am schnellsten per Sky Map (R3 auf der Karte) in den Abyss über dem Camp schnellreisen und hinunterspringen. Die Cutscene im schwarzen Hauptzelt (Beginn des Harvest Festival in Hernand Castle) beendet Kapitel 4.","conf":"high"}],"boss":"Tenebrum","warn":"On the Right Path: Focused Force Palm verpassen möglich (falscher Weg zu Scholastone). Hologramm bleibt zugänglich — Karte zeigt Ort. Kap. 9 Auto-Unlock falls weiterhin verpasst."},
  {"ch":"5","name":"Guest Unbidden","quests":[{"q":"Double-sided Invitation","trigger":"Startet automatisch per Cutscene in der Region Hernand zu Beginn von Kapitel 5","prereq":"Casted Shadow (laut PowerPyx; game8 nennt 'Forbidden Knowledge' als Vorquest)","reward":"—","miss":false,"tip":"Reine Story-Quest ohne Gameplay: Das einzige Ziel 'Speak with Marius' schließt direkt nach der ersten Cutscene automatisch ab. Marquis Serkis kündigt die Demenissian-Delegation an und lädt die Greymanes zum Bankett; anschließend gilt es, die untergetauchte Demenissianerin Damiane zu finden.","conf":"medium"},{"q":"Unwelcomed Guests","trigger":"Feld nördlich von Hernand Castle (am Stadttor): Soldaten bei der Kutsche mit dem panischen Pferd ansprechen (Cutscene)","prereq":"Double-sided Invitation","reward":"—","miss":false,"tip":"Das frei im Kreis laufende weiße Pferd (nicht die Kutschpferde) besteigen und zähmen: linken Stick entgegen der Bewegungsrichtung des Pferdes drücken, bis der gelbe Fortschrittskreis voll ist; wirft es einen ab, einfach erneut aufsitzen. Danach das gezähmte Pferd zum Stall nördlich bringen und dort mit Damiane sprechen.","conf":"high"},{"q":"Demenissian Delegation","trigger":"Innenhof von Hernand Castle: das Bankett besuchen und mit Marquis Serkis bzw. Barden Middler und Alan Serkis sprechen","prereq":"Unwelcomed Guests","reward":"The Grove's Thorn (One-Handed Mace), Swift I, Howling of Chaos (laut PowerPyx 'Gale I' statt 'Swift I'; game8 und Fextralife nennen 'Swift I')","miss":false,"tip":"Beim Bankett entkommt die als 'Geschenk' präsentierte Bestie – Bossfight gegen Kearush the Slayer mit drei Phasen/Lebensbalken. Vorher Ausrüstung auf Verfeinerung 4+ bringen, Plattenrüstung beim Händler in Hernand kaufen und 100–200 Grilled Meat einpacken. Per Vorwärts-rechts-Dodge hinter den Boss kommen und kurze Kombos setzen; in Super-Armor-Phasen hinter die Arenawände sprinten, notfalls Palmer Pills zur Selbstwiederbelebung. game8-Alternative: mit dem Back-Hang-Skill hohen Schaden machen.","conf":"medium"},{"q":"Exposed Plot","trigger":"Direkt nach dem Kearush-Kampf: hinterer Ausgang der Kirche in Hernand","prereq":"Demenissian Delegation","reward":"—","miss":false,"tip":"Kurze Story-Quest: die Kirche hinten rechts verlassen und im Hinterhof Damiane ansprechen. Die Cutscene enthüllt, dass Demeniss als heimlicher Lieferant der Black Bears agiert. Kein Kampf nötig.","conf":"high"},{"q":"The Missing Seal","trigger":"Startet automatisch nach Exposed Plot (Region Hernand); erster Schritt ist das Lesen des 'Unsealed letter' im Inventar","prereq":"Exposed Plot","reward":"Core Blueprint: Haste","miss":false,"tip":"Den 'Unsealed letter' (lila Schlüsselitem) lesen, dann im Journal unter Faction Quests > Witches die Quest 'Witch of Wisdom' tracken – erste Hauptquest, die eine Faction Quest voraussetzt. Östlich des Scholarship Institute die Gegner an der Hexenhütte besiegen, durchs Dachfenster einsteigen, die Hexe befreien und das Abyss Artifact vom Tisch nehmen. Anschließend im Witch's House in The Witchwoods (laut game8: die Hexe Elowen, Alfonso Estate) 'Listen to Request' wählen.","conf":"high"},{"q":"Crowcaller","trigger":"Innerer Burghof von Hernand Castle nahe dem Kircheneingang: Soldaten ansprechen (Cutscene über Geister im Schloss)","prereq":"The Missing Seal","reward":"—","miss":false,"tip":"Im 2. Stock des Schlosses durch die linke Holztür zum Abyss Gate (gelbe Wand) und in die Abyss-Himmelskarte teleportieren (laut game8: Eindringling mit der Laterne bis zum Gate verfolgen, Ziel ist das Axiom Archive). Dort geradeaus zum hohen Turm, die Gegner besiegen – die Abschluss-Cutscene folgt automatisch. Reagiert das Gate nicht, über die Karte dorthin schnellreisen.","conf":"high"},{"q":"The Crow's Warning","trigger":"Questmarker etwas südlich von Hernand town (laut game8: Muckroot Ranch)","prereq":"Crowcaller","reward":"—","miss":false,"tip":"Zum Haus am Marker südlich der Stadt reiten und die Cutscene mit dem krähenhaften Fremden auslösen, der auffällig viel über die Greymanes weiß. Danach den Hinterhalt überstehen und die Männer des Crowcallers besiegen – mehr ist nicht zu tun.","conf":"high"},{"q":"Bloodwind","trigger":"Questmarker in Zentral-Demeniss (auf der Weltkarte direkt nördlich des 'M' in 'DEMENISS'); Cutscene beim Annähern an die Leichen im Hof","prereq":"The Crow's Warning","reward":"—","miss":false,"tip":"Nach der Cutscene erst die Gegner, dann den Crowcaller selbst stellen – hier nur 1 Lebensbalken (laut game8 an der Church of West Demeniss; er flieht nach dem Kampf). Taktik: Angriffe mit L1 parieren und jeweils eine leichte Kombo nachsetzen. Vorher Grilled Meat zum Heilen bunkern (Fleischhändler und Kochtopf in Hernand).","conf":"high"},{"q":"Secret at the Church","trigger":"Region Demeniss, nach Bloodwind: Tür im Norden des Orphanage-Hofs untersuchen (Cutscene mit Abbess Marina)","prereq":"Bloodwind","reward":"—","miss":false,"tip":"In der Krypta hinter der südlich gelegenen Kirche die Puzzle-Box auf dem Altar lösen – die Eckknöpfe in der Reihenfolge oben-links, unten-rechts, unten-links, oben-rechts drücken – und den Dagger of Radiance einsammeln. Danach den Pillar of Radiance (zwischen Kirche und Orphanage) mit L1/LB anvisieren, interagieren und die konzentrischen Scheiben so drehen, dass das 'Auge'-Symbol entsteht.","conf":"high"},{"q":"Toward the Nest","trigger":"Spire of Soaring in Nord-Demeniss; startet nach Secret at the Church","prereq":"Secret at the Church","reward":"Blackwing Leather Armor (Body), Blackwing Mask (Head), Tauria Curved Sword","miss":false,"tip":"Im Spire über die Höhle an der rechten Klippe bzw. Force Palm und die Windplattform nach oben; mit Axiom Force die Energieflüsse über die Wandpaneele umleiten und das zentrale Paneel zweimal drehen. Oben die Crescent Skybridge aktivieren: vier Orb-Lichtstrahlen auf die Wandpaneele ausrichten, zwei gelbe Stromkabel reparieren, das runde Wandpaneel mit Force Palm anschlagen und den Pfeiler drehen, bis er blau leuchtet. Am Crow's Nest erst die Crow Brothers, dann Draven the Crowcaller mit 3 Lebensbalken besiegen – mit L1 kontern, Grappling/Lariat für hohen Stagger nutzen und reichlich Heilessen (100+ Grilled Meat) mitnehmen. Während des Kampfes lässt sich der Skill Aerial Roll lernen.","conf":"high"}],"boss":"Kearush the Slayer (Demenissian Delegation) + Draven the Crowcaller","unlock":"Witch Elowen (The Missing Seal)"},
  {"ch":"6","name":"Cracks in the Shield","quests":[{"q":"News","trigger":"Soldat/Bote am Greymane-Camp (Howling Hill, Hernand) bittet zum Treffen auf Hernand Castle","prereq":"Toward the Nest (Spire of Soaring) (Kapitel 5)","reward":"—","miss":false,"tip":"Reines Story-Quest ohne Kampf: Im Greymane-Camp mit dem Soldaten bei den Hauptzelten sprechen (Cutscene), dann in Hernand Castle vom Haupteingang rechts die Treppe hinauf in den Raum im 2. Stock zu Marquis Serkis – Calphade wird angegriffen.","conf":"high"},{"q":"To the Battlefield","trigger":"Bei der Soldatengruppe am Beacon-Turm auf dem Hügel nordwestlich der Stadt Hernand","prereq":"News","reward":"—","miss":false,"tip":"Dem Guide zu Pferd über den Bergpfad folgen und am Überfallort die Leiche untersuchen – der folgende Black-Bears-Hinterhalt lässt sich besiegen oder (laut game8) umgehen. Danach dem Soldaten zum Calphade-Camp folgen und am Tor Barden Middler treffen; mit ihm durchs Lager gehen.","conf":"high"},{"q":"The Counterattack","trigger":"Markiertes Soldatencamp in Hernand; ein Scout zu Pferd wartet","prereq":"To the Battlefield","reward":"—","miss":false,"tip":"Mit dem Scout zum verbündeten Außenposten reiten, das gefallene Calphade-Banner mit Nature's Grasp (Dreieck+Kreis / Y+B) aufheben, über die Holztreppe zur Plattform tragen und mit L1+Viereck / LB+X in die Halterung setzen. Nature's Grasp läuft auf Zeit – fällt das Banner, einfach erneut aufnehmen. Kein Kampf nötig.","conf":"high"},{"q":"Cradle of Defense","trigger":"Schließt nach The Counterattack automatisch auf dem Schlachtfeld bei Calphade an","prereq":"The Counterattack","reward":"—","miss":false,"tip":"Nacheinander Banner-Piken an drei Orten aufstellen: Siege Armory, Gunpowder Mill (mit Elite-Gegnern) und Thalwynd – jeweils per Nature's Grasp tragen und mit L1+Viereck einsetzen; mit dem Setzen klären sich die Gegnerwellen. Bei Thalwynd schützt die Zeitlupe von Nature's Grasp vor dem Artilleriebeschuss. Tauria Curved Sword + Nature's Echo empfohlen; West-Wachposten erlauben alle 5 Spielstunden Rast/Heilung. Auf Grappler achten (Quick-Time-Events).","conf":"high"},{"q":"The Touch of Deliverance","trigger":"Beim Southern Guard Post des Camps; Soldaten geben Health-Booster und 10 Whistling Arrows","prereq":"Cradle of Defense","reward":"—","miss":false,"tip":"Whistling Arrows (links halten + R2/RT) rufen Bombardements auf Artillerietürme und sind an befreundeten Camps nachfüllbar. Das markierte Feindcamp nordöstlich räumen, den verwundeten Soldaten am Ende des Camps mit Viereck/X aufnehmen und – auch zu Pferd möglich – zum Southern Guard Post zurückbringen. Hinweis: game8 führt die Quest als 'Hand of Deliverance'.","conf":"medium"},{"q":"Fire on the Frontlines","trigger":"Schließt an The Touch of Deliverance an; Ziel ist die Kirche von Calphade","prereq":"The Touch of Deliverance","reward":"—","miss":false,"tip":"Gegner vor der Kirche besiegen, drinnen den Versorgungswagen am Altar mit Concentrating Light (L1+R1, dann L1; game8 nennt den Skill 'Blinding Light') an den Holzteilen anzünden, ca. 30 Sekunden brennen lassen und dann mit Nahkampfschlägen zerstören – normale Treffer allein bewirken nichts. Die Glocke auf der Kirche ist während der Belagerung funktionslos; sie kann erst nach Kapitel 6 geläutet werden (deckt Karte in Nord-Hernand auf).","conf":"medium"},{"q":"Fire Support","trigger":"Soldat an der Artilleriestellung (Gunsite) im Norden ansprechen","prereq":"Fire on the Frontlines","reward":"Whistling Arrow x10","miss":false,"tip":"Erst das Kanonenrad per Interaktion reparieren, dann mit den Wallkanonen vier Wachtürme der Black Bears zerstören – erkennbar am schwarzen Rauch. Meist genügt ein Treffer pro Turm; trifft man seitlich, ist ein zweiter Schuss nötig.","conf":"high"},{"q":"In Ashes","trigger":"Camp am Stadtrand (den Hügel nordwärts hinab): mit den streitenden Soldaten sprechen","prereq":"Fire Support","reward":"—","miss":false,"tip":"Das zentrale befestigte Black-Bears-Lager durch den offenen Haupteingang stürmen, Gegner ausdünnen und den hammerschwingenden Black Bear Captain (Miniboss) besiegen. Whistling Arrows für Flächen-Bombardements sind laut beiden Quellen hier hervorragend. Nach dem letzten Gegner zeigt eine automatische Cutscene die Befreiung der Gefangenen.","conf":"high"},{"q":"Hidden Fangs","trigger":"Schließt automatisch an In Ashes an; Suchgebiet auf dem Schlachtfeld","prereq":"In Ashes","reward":"—","miss":false,"tip":"Fünf Black-Bears-Battle-Tanks (hölzerne Belagerungspanzer, feuern Kanonen bei Annäherung) zerstören – am sichersten aus Distanz per Whistling Arrow, der ein Bombardement auf den Tank ruft. Die Tanks fahren über die offenen Felder südlich des Suchgebiets, einer steht zentraler; zu Pferd absuchen und Pfeile an befreundeten Camps auffüllen. Gegner respawnen hier – laut PowerPyx gut zum Farmen von Abyss Artifacts.","conf":"high"},{"q":"Reclamation","trigger":"Automatisch per Cutscene nach Hidden Fangs","prereq":"Hidden Fangs","reward":"—","miss":false,"tip":"Kein eigenes Gameplay: Das Ziel 'Defeat the enemies surrounding the outer bailey' wird laut PowerPyx automatisch in derselben Cutscene wie der Abschluss des Vorgänger-Quests erledigt; die Black Bears ziehen sich zum Calphade Castle zurück.","conf":"high"},{"q":"A Thousand Troops","trigger":"Nach Reclamation südwärts zum Calphade Castle vorrücken","prereq":"Reclamation","reward":"—","miss":false,"tip":"Praktisch nur zwei Cutscenes in Folge: Durch die zurückweichenden Black Bears zum Schloss (Kämpfe lassen sich umgehen), am Eingang auf Oongka treffen (man spielt weiter Kliff); im Schloss löst die Szene mit Stefan Lanford den automatischen Abschluss aus.","conf":"high"},{"q":"Traitor","trigger":"Direkt im Calphade Castle im Anschluss an A Thousand Troops","prereq":"A Thousand Troops","reward":"Shield of Betrayal","miss":false,"tip":"Bossfight gegen den Schildträger Cassius Morten (eine Lebensleiste, lange Angriffsketten). PowerPyx: Tauria Curved Sword + Kliffs Skill Nature's Echo, schwere Angriffe (R2/RT) spammen – sie schaden auch durch den Block, nach drei Treffern ist er unterbrochen und für leichte Angriffe offen. game8-Alternative: umgestürzte Säulen per Nature's Grasp auf ihn schmettern. Vorab ca. 50 Grilled Meat am Kochtopf in Hernand vorbereiten; Rückreise zum Nachkaufen ist möglich.","conf":"high"},{"q":"All Quiet on the Front","trigger":"Automatisch per Cutscene nach dem Sieg über Cassius Morten","prereq":"Traitor","reward":"—","miss":false,"tip":"Reine Cutscene: Marquis Lanford wird die Nachricht überbracht, Calphade Castle ist befreit. Das Quest schließt sich von selbst ab.","conf":"high"},{"q":"News of Victory","trigger":"Nach All Quiet on the Front dem Soldaten aus der Boss-Arena folgen","prereq":"All Quiet on the Front","reward":"—","miss":false,"tip":"Mit dem Soldaten den langen Ritt zum Calphade Beacon hinauf, im Turm die Treppe hochsteigen und die Feuerschale entzünden. Am einfachsten per Concentrating Light (L1+R1, dann L1); alternativ einen Pfeil an einer Wandfackel entzünden und auf die Schale schießen – das Pfeil-Teilziel ist laut PowerPyx irreführend formuliert.","conf":"high"},{"q":"Return Home","trigger":"Am Greymane-Camp (Howling Hill): die Gefährten am Zelt ansprechen","prereq":"News of Victory","reward":"—","miss":false,"tip":"Das Gespräch mit den Gefährten (laut game8: Yann, Duane, Oongka) löst die Abschluss-Cutscene aus und startet unmittelbar Kapitel 7 ('Ashes of Treachery'), das für längere Zeit in eine neue Region führt. PowerPyx rät dringend, vorher rund 100 Grilled Meat einzupacken.","conf":"high"}],"boss":"Cassius Morten","warn":"Bell Tower Calphade während der Kap.-6-Belagerung funktionslos — erst nach Kapitelabschluss läutbar (deckt Karte Nord-Hernand auf); nichts permanent verpassbar."},
  {"ch":"7","name":"Homecoming","quests":[{"q":"Ashes of Treachery","trigger":"Startet automatisch nach der vorherigen Hauptquest in der Hernand-Region (Ritt mit den Gefährten)","prereq":"Return Home (Kapitel-6-Abschluss)","reward":"—","miss":false,"tip":"Mit den Gefährten zum niedergebrannten Haus reiten und die Gegner dort ausschalten. Am Schrein links vor dem Haus den Brief aus dem Maul der Statue nehmen und im Inventar den lila Brief 'Beighen Situation Report' lesen. Danach der Straße nach Norden Richtung Beighen folgen.","conf":"medium"},{"q":"Trust Lost","trigger":"Bei Ankunft in Beighen village (Hernand)","prereq":"Ashes of Treachery","reward":"—","miss":false,"tip":"Am Dorfeingang mit den Leuten auf der Straße sprechen, dann nach Norden bis zur nächsten Kreuzung: Dort warten Naira und Andrew am roten Zaun. Reine Dialogquest ohne Kampf – die Dorfbewohner sind den Greymanes offen feindselig gesinnt.","conf":"medium"},{"q":"Bared Fang","trigger":"In Beighen village, direkt im Anschluss an Trust Lost","prereq":"Trust Lost","reward":"—","miss":false,"tip":"Lausch-Quest: An der roten Scheune am Ostrand mit L3 an die Außenwand lehnen (nicht durchs Fenster schauen). Dann beim Wächter westlich des Dorfs mit den 'Lie'-Dialogoptionen über Untergrundlager und Beighen Tribe täuschen, anschließend im leeren Haus im Dorfzentrum und an der roten Hütte weiter lauschen. Zum Schluss erneut mit dem Wächter sprechen und durch die Falltür hinabsteigen (Cutscene).","conf":"medium"},{"q":"Rekindled Hope","trigger":"Direkt nach Bared Fang (Torstein-Cutscene im Untergrund, Hernand)","prereq":"Bared Fang","reward":"—","miss":false,"tip":"Nach dem Gespräch mit Torstein die Leiter hinauf und dem berittenen Blue-Fangs-Soldaten folgen, dann allein durch den Wald zum Beacon Tower. Dort wartet ein teleportierender Miniboss-Kommandant (viel HP, kein sichtbarer Lebensbalken) – warten, bis er aufhört zu teleportieren, dann zuschlagen. Oben die Feuerschale mit Concentrating Light entzünden. Vorab lohnt der Schnellreisepunkt in Beighen (Kochtopf vorhanden).","conf":"medium"},{"q":"Podium of Resolve","trigger":"In Beighen Village beim Blue-Fangs-Wächter; ggf. Wartezeit bis 22:00 Uhr überspringen","prereq":"Rekindled Hope","reward":"—","miss":false,"tip":"Torstein in Beighen treffen – steht 'Wait for the right time', per Options-Menü auf 22:00 Uhr vorspulen und das Haus hinter den Wachen betreten. Nach Torsteins Rede im Hof durch die Falltür der Hütte in den Tunnel, am Ende die Kryptatür öffnen und am Altar Jian's Sword holen (Cutscene). Kaum Kampf.","conf":"medium"},{"q":"Shadows Over Pailune","trigger":"Torstein an der Brücke in Beighen treffen","prereq":"Podium of Resolve","reward":"Jackal's Leather Helm + Jackal's Leather Armor + Jackal's Cloth Cloak","miss":false,"tip":"Mit Torstein von der Beighen-Brücke aus reiten, bis die Cutscene auslöst. Danach allein nach Norden durch den Wald zur roten Hütte am Questmarker (Safe House bei Pailune) und eintreten. Story: Shane befreien und die Sprengung der Burgmauer planen.","conf":"medium"},{"q":"Driving out the Shadows","trigger":"Direkt nach Shadows Over Pailune; markiertes Haus betreten (Hernand)","prereq":"Shadows Over Pailune","reward":"—","miss":false,"tip":"Im markierten Haus die Cutscene mit dem schwer verletzten Shane auslösen. Dann die zwei Fässer und die Leiche neben der Tür verschieben – darunter liegt eine rote Falltür mit dem Sprengsatz. Den Sprengstoff im Hafen am letzten Dock am kleinen Boot anbringen (Taste halten); Stealth unnötig, man kann an allen Gegnern vorbeirennen.","conf":"medium"},{"q":"Lurking Wolves","trigger":"Haus in der Mitte von Pailune betreten (Cutscene)","prereq":"Driving out the Shadows","reward":"—","miss":false,"tip":"Einfach zum Haus im Zentrum von Pailune laufen – Entdeckung durch Gegner ist egal, man kann an allen vorbeirennen. Beide Ziele erledigen sich in derselben Cutscene; unmittelbar danach beginnt die große Schlacht um Pailune.","conf":"medium"},{"q":"Reclamation","trigger":"Schließt direkt an Lurking Wolves an (Schlacht um Pailune)","prereq":"Lurking Wolves","reward":"—","miss":false,"tip":"Pailune einnehmen: alle Gegner besiegen, bis die Prozentanzeige am linken Bildschirmrand auf 0 % sinkt – einige Minuten Dauerkampf ohne Boss. Die geschlagenen Jackals fliehen in die innere Festung.","conf":"medium"},{"q":"Lonely Jackals","trigger":"Direkt nach Reclamation; in der Festung die Treppe hinauf ins Gebäude (Bosskampf)","prereq":"Reclamation","reward":"Cloak – Hungering Fang Leather Cloak, Shoes – Hungering Fang Leather Boots","miss":false,"tip":"Bossfight gegen Ludvig (2 Phasen, Blitzschaden): Ausweichen statt Blocken/Parieren. Er teleportiert ständig – warten, bis er Kombos verfehlt oder kurz stehen bleibt, dann leichte Angriffskombos. In Phase 2 (nach der Verwandlung) greift er fast pausenlos an: weiter ausweichen und parallel heilen; PowerPyx empfiehlt 100+ Grilled Meat als Vorrat.","conf":"medium"},{"q":"Resolution","trigger":"Automatisch nach Lonely Jackals (Hernand)","prereq":"Lonely Jackals","reward":"—","miss":false,"tip":"Zum Haus des Bosskampfs zurückkehren und die Gefährten ansprechen (Cutscene). Danach in Pailune die Glocke läuten, um die Region zu entnebeln, und den Schnellreisepunkt nördlich der Stadt freischalten. Vor dem Weiterspielen 100+ Grilled Meat für die kommenden Bosskämpfe bunkern – Kochtöpfe stehen im Soldatenlager im Süden von Pailune.","conf":"medium"},{"q":"The Counterattack","trigger":"Rotes Haus nördlich von Pailune an der Hauptstraße","prereq":"Resolution","reward":"—","miss":false,"tip":"Kurze Übergangsquest: der Hauptstraße nach Norden folgen und im roten Haus die Gefährten treffen; das Ziel 'Wait for the right moment' erledigt sich automatisch in der Cutscene. Leitet die Entscheidungsschlacht gegen die Black Bears am Silverwolf Mountain ein.","conf":"medium"},{"q":"Unleashed Fury","trigger":"Automatisch nach The Counterattack; Sammelpunkt an der Holzbrücke","prereq":"The Counterattack (Kapitel 7)","reward":"—","miss":false,"tip":"Zum Questmarker an der Holzbrücke laufen, sich der Armee anschließen und an der Front die Gegner auf der Brücke bekämpfen, bis die Cutscene auslöst. Kein Boss, keine Sondermechaniken – kurze Schlachtsequenz.","conf":"medium"},{"q":"The Final Bridge","trigger":"Automatisch nach Unleashed Fury (Schlachtfeld am Silverwolf Mountain)","prereq":"Unleashed Fury","reward":"—","miss":false,"tip":"Der Straße bergauf folgen und die Questmarker nacheinander abklappern: an jedem wartet ein Gefährte (Andrew, Naira, Duane, Oongka, Yann, Shane), dem man per Cutscene im Kampf beisteht. Gegner auf dem Weg komplett ignorieren und vorbeirennen – Heilitems für den kommenden Bosskampf aufsparen.","conf":"medium"},{"q":"Broken Claws","trigger":"Automatisch nach The Final Bridge (Bergstraße)","prereq":"The Final Bridge","reward":"—","miss":false,"tip":"Sehr kurze Quest: die Bergstraße hinauf zum rot markierten Lager und das Ashclaw slave camp befreien, indem alle Gegner dort ausgeschaltet werden. Danach weiter bergauf zur nächsten Hauptquest.","conf":"medium"},{"q":"Battle at Silverwolf Mountain","trigger":"Automatisch nach Broken Claws; Aufstieg zum Gipfel","prereq":"Broken Claws","reward":"Sword – Melted Ambition","miss":false,"tip":"Auf dem Weg zum Gipfel das verschlossene Tor mit Nature's Grasp anheben und dem linearen Burgpfad bis zur Leiter folgen – dann Bosskampf gegen Myurdin (2 Phasen/2 Lebensbalken). Phase 1: konsequent parieren und schwere Angriffe einstreuen (Tauria Curved Sword effektiv). Phase 2: Myurdin verwandelt sich und nutzt Lava-/Feuerangriffe – auf Ausweichen und Ausdauer-Management umstellen.","conf":"high"},{"q":"Incomplete Victory","trigger":"Automatisch nach dem Sieg über Myurdin","prereq":"Battle at Silverwolf Mountain","reward":"—","miss":false,"tip":"Reine Story-Sequenz nach dem Bosskampf: Kliff kuriert seine Verletzungen aus, Oongka übernimmt die Säuberung der Gegnerreste. Das einzige Ziel ('mit Oongka sprechen') schließt automatisch mit der Cutscene ab, in der man erstmals Oongka spielt. Kein Kampf.","conf":"medium"},{"q":"Ludvig's Whereabouts","trigger":"Siedlung südöstlich von Pailune (Hernand)","prereq":"Incomplete Victory","reward":"—","miss":false,"tip":"Zur Ortschaft südöstlich von Pailune reisen und dort Duane und Shane ansprechen – die Cutscene beendet die Quest. Story: Ein kleiner Elitetrupp nimmt die Verfolgung Ludvigs auf, da Jackals und Black Bears inzwischen unabhängig operieren. Kein Kampf.","conf":"medium"},{"q":"Time to Face Justice","trigger":"Questmarker auf einem Feld (Hernand); Mann am gebrochenen Baumstamm ansprechen","prereq":"Ludvig's Whereabouts","reward":"Sword – Ignir, Body Armor – Solas Plate Armor, Boots – Solas Plate Boots","miss":true,"tip":"Ludvigs Spur mit L1+R1 (gelber Pfad) bis zu einem kleinen Gehege verfolgen und das Blut in der Mitte untersuchen – löst den Bosskampf gegen One-Armed Ludvig aus (nur 1 Lebensbalken), den man zwangsweise als Oongka bestreitet: Doppelschwerter anlegen, mit L1 parieren und leichte R1-Kombos ansetzen. VERPASSBAR laut PowerPyx: Vor dem letzten Ziel alle Oongka gegebenen Waffen/Ausrüstungen ablegen – er wird danach längere Zeit unspielbar und seine Ausrüstung ist bis zu seiner Rückkehr unzugänglich. Zum Abschluss zurück zum Friedhof von Pailune (Kapitelende).","conf":"high"}],"boss":"Ludvig (Lonely Jackals) + Myurdin (2 Phasen, Lava) + One-Armed Ludvig","unlock":"Oongka (scripted). PERMANENT erst nach 2 Kap.-8-Quests!"},
  {"ch":"8","name":"Blood Coronation","quests":[{"q":"Healing Pailune","trigger":"Startet automatisch nach Kapitel 7; Lager nördlich der Stadt Pailune (Hernand), Treffen mit Torstein","prereq":"Time to Face Justice","reward":"—","miss":false,"tip":"Zum Lager nördlich von Pailune reisen und Torstein treffen, dann ihm zu den Docks folgen. Dort übergibt er einen Brief (Maegu's Letter), der die nächste Quest auslöst. Reine Story-Quest ohne Kampf; Hintergrund ist die Verfolgung Myurdins nach Demeniss.","conf":"high"},{"q":"A Bond","trigger":"Folgt direkt auf 'Healing Pailune'; Maegu's Letter aus dem Inventar lesen (Hernand)","prereq":"Healing Pailune","reward":"—","miss":false,"tip":"Maegu's Letter von Torstein im Inventar lesen, dann zum abgelegenen Bambuswald südlich von Demeniss bzw. südöstlich des alten Greymane-Camps reisen (Teleport zum Abyss über dem Camp spart Zeit). Am Altar die zwei Steinlaternen anzünden. Widerspruch: game8 ordnet das Laternen-Anzünden erst 'Ritual Preparations' zu, bei PowerPyx beendet es diese Quest.","conf":"medium"},{"q":"Ritual Preparations","trigger":"Nach 'A Bond' am Altar; führt zur Shipwreck Shore (Hernand)","prereq":"A Bond","reward":"—","miss":false,"tip":"An der Shipwreck Shore Gegner räumen, die blauen Geister mit der Laterne anleuchten bis 'Learning in Progress' erscheint und mit dem Visione-Helm die 'Memory of the Kidnapped Witches' ansehen. Drei Items für Maegu einsammeln: Talisman (im Sand am Nordrand), Bells (im Sand am Südrand) und Censer unter dem großen Schiffswrack. Fürs Censer das Wrack mit Nature's Grasp anheben, das Item schnell greifen und das Wrack wieder loslassen — der Schritt ist fummelig.","conf":"high"},{"q":"Where the Wind Guides You","trigger":"Nach 'Ritual Preparations'; Rückkehr zum Altar im Bambuswald, Ritual ausführen","prereq":"Ritual Preparations","reward":"Weapon (Lance) – Golden Vanguard + 1 Abyss Artifact (game8 listet für Ashen Steps zusätzlich Radiant Necklace x1)","miss":false,"tip":"Am Altar das Ritual ausführen, dann zur Festung im Nordosten (game8: Fort Ironclad) — mit dreifachem Force-Palm-Sprung lassen sich die Mauern überspringen und alle Gegner ignorieren. Boss Gregor (Speer): seitlich ausweichen statt blocken, seine Super-Armor-Stiche kommen wiederholt; laut game8 ist er langsam genug für Perfect Parries. Danach Woosa (Hexe im lila Kleid) aufs Pferd nehmen und zum Altar im Bambuswald zurückreiten.","conf":"high"},{"q":"Chasing a Shadow","trigger":"Nach 'Where the Wind Guides You'; altes Greymane-Camp am Howling Hill","prereq":"Where the Wind Guides You","reward":"—","miss":false,"tip":"Zum alten Greymane-Camp am Howling Hill zurückkehren und am Schrein-Eingang das Dragon Totem untersuchen. Anschließend den violetten Brief 'Report on Myurdin's Whereabouts' aus dem Inventar lesen — er entlarvt Count Azerians Manor als Herz des Demeniss-Spionagenetzwerks.","conf":"high"},{"q":"Blazing Fire","trigger":"Quest-Marker in der Region Demeniss, knapp südlich der 'DE'-Kartenbuchstaben (Rustleaf Farm)","prereq":"Chasing a Shadow","reward":"Formal alliance with House Azerian (Story-Ergebnis laut PowerPyx, kein Item)","miss":false,"tip":"Erst zur Rustleaf Farm, dann nordöstlich zum Azerian Manor. Übers Dach auf den Balkon und unentdeckt hinein; im Obergeschoss dreht sich eine auffällig andersfarbige Wand zum Geheimraum mit dem Investigative Report am Bett. Entdeckung ist kein Questfehlschlag — Wachen dürfen ausgeschaltet werden; wird man niedergerungen, schnell Dreieck/Y drücken (zweimal hintereinander verlorenes QTE = Rauswurf).","conf":"high"},{"q":"Whispering Shadows","trigger":"Nach 'Blazing Fire'; Sungrove Manor nahe dem Endpunkt der Vorquest","prereq":"Blazing Fire","reward":"—","miss":false,"tip":"Sungrove Manor infiltrieren; Kämpfe mit den Wachen sind erlaubt, Grapple-QTEs mit Dreieck/Y kontern. Zwei Erinnerungen mit dem Visione-Helm ansehen: oben im Hauptbüro (Azerian) und unten im Flur (Bastier) — jeweils die blauen Geister mit L1/LB anschauen bis 'Learning in Progress' voll ist, dann über das Options-Menü das Memory Fragment abspielen.","conf":"high"},{"q":"Bloodied Invitation","trigger":"Nach 'Whispering Shadows'; Manor-Infiltration (game8: Windmere Manor)","prereq":"Whispering Shadows","reward":"—","miss":false,"tip":"Übers Dach auf den vorderen Balkon klettern und durch die Balkontür einsteigen. Count Byron in seinem Büro im Obergeschoss (game8: kleiner Raum mitten im Flur) unbemerkt mit dem Attentats-Prompt (Quadrat/X) ausschalten. Bei Entdeckung werfen die Wachen einen nur raus — beliebig viele Versuche, die Quest scheitert nicht.","conf":"high"},{"q":"Resolve Amidst a Storm","trigger":"Nach 'Bloodied Invitation'; Rückkehr zu Countess Azerian in ihrem Manor","prereq":"Bloodied Invitation","reward":"—","miss":false,"tip":"Kurze reine Dialog-Quest: zurück zum Azerian Manor und oben (wo man sie zuvor traf) mit Countess Azerian sprechen. Sie erklärt, dass Duke Wells unterstützt werden muss, um politische Verbündete zu sichern. Kein Kampf.","conf":"high"},{"q":"Preparations for Advance","trigger":"Nach 'Resolve Amidst a Storm'; Soldatenlager am Marker (game8: Thornbriar Outpost)","prereq":"Resolve Amidst a Storm","reward":"—","miss":false,"tip":"Im markierten Soldatenlager das weiße Zelt ansteuern (game8: mit dem Offizier der Baracken sprechen) — Cutscene beendet die Quest. Vorher vorbereiten: PowerPyx empfiehlt 200+ Grilled Meat (+80 HP pro Stück) für die kommende Großschlacht samt Bossfight; Fleisch jagen oder bei Händlern in Hernand/Pailune kaufen und an Kochtöpfen grillen (z. B. rechts vom Hernand-Fleischhändler).","conf":"high"},{"q":"Rebel Suppression","trigger":"Nach 'Preparations for Advance'; Großschlacht um die Festung (game8: Thornbriar Fortress)","prereq":"Preparations for Advance","reward":"—","miss":false,"tip":"Lange Großschlacht: die Gegner-Leiste links auf 0 % bringen und alle 3 Siege Towers zerstören — per Kanone beschießen oder mit Focused Light anzünden und mit dem Turning-Slash-Skill nachsetzen. Der Cursed Knight taucht am ersten Turm auf und respawnt an den weiteren. Tauria Curved Sword (Heavy Attack) räumt Gruppen gut, nicht hinter berittene Gegner stellen, Grapple-QTEs kontern. Hier ist laut PowerPyx die beste von sehr wenigen Gelegenheiten für Battle Challenge 6 'Into the Barrage' (5 Gegner mit 1 Kanonenschuss).","conf":"high"},{"q":"The Cursed Knight","trigger":"Direkt nach 'Rebel Suppression'; höchster Punkt des Burghofs der eroberten Festung","prereq":"Rebel Suppression","reward":"Weapon (Sword) – Shackle of Might + 1 Abyss Artifact","miss":false,"tip":"Bossfight gegen den Cursed Knight (game8/TheGamer: Fortain) — Humanoid mit Schild, der wiederholt einen Geisterritter beschwört; beide teilen sich eine HP-Leiste. Tauria's Curved Sword (von Boss Crowcaller) mit dem grünen Skill Nature's Echo verdoppelt den Heavy-Schaden; Heavy-Kombos mit leichten Schlägen mischen und wegrollen, sobald der blaue Geist erscheint. Der Boss teilt stark aus — hochwertiges Essen einpacken.","conf":"high"},{"q":"The Blood Coronation","trigger":"Nach 'The Cursed Knight'; Palast in der Demeniss-Hauptstadt","prereq":"The Cursed Knight","reward":"—","miss":false,"tip":"Im Palast die feindlichen Wachen bekämpfen (kostet keine Reputation), im Büro/Festsaal im 2. Stock die blauen Geister mit L1/LB studieren und das Memory Fragment per Visione-Helm starten. Wichtig: den Visione-Modus nicht verlassen (kein Kreis/B) — sonst muss man die Erinnerung oben neu starten; den Geistern in die Audience Chamber folgen und dort die drei helleren Geister untersuchen. Danach erscheint Gabriel Caliburn: Die Niederlage ist geskriptet (PowerPyx/VGC/method.gg), keine Heilitems verschwenden — game8s 'Defeat him to progress' ist irreführend. Weiter geht es als Damiane.","conf":"high"},{"q":"Clue","trigger":"Startet automatisch nach 'The Blood Coronation'; man spielt Damiane (Kliff nicht verfügbar), Demeniss-Hauptstadt","prereq":"The Blood Coronation","reward":"—","miss":false,"tip":"Als Damiane zum Marker in der Demeniss-Hauptstadt; die feindlichen Wachen kann man umrennen oder töten (Grapples vermeiden). Im Gebäude im Suchgebiet die Trapdoor im Boden des Seitenraums öffnen (game8: vorher die Wache am Schreibtisch leise ausschalten) und ins Untergrundgefängnis hinabsteigen. Beatrice Azerian findet man tot in der letzten Zelle. Laut PowerPyx-Kommentaren muss man das Demeniss Castle nach der Cutscene verlassen, damit das Questziel sauber abschließt.","conf":"high"},{"q":"A Fleeting Dream","trigger":"Nach 'Clue'; Bosskampf im Osten von Demeniss (game8: Breezeblown Knoll), weiterhin als Damiane","prereq":"Clue","reward":"Official Knight's Plate Armor, Official Knight's Leather Boots, Official Knight's Leather Gloves, Official Knight's Plate Gloves + Spire of Clockwork Key (PowerPyx; game8 nennt statt der Plate Gloves 'Eclipsed Solas Plate Gloves' und zusätzlich Damiane's Ponytail Ticket x1)","miss":false,"tip":"Zwei-Phasen-Bossfight als Damiane gegen Lucian Bastier. Phase 1 (Schild + explosive Feuer-Mace): er blockt frontal alles, also seitlich um ihn herumrollen und mit der Golden Vanguard (R1-Angriffe) seine Deckung brechen. Phase 2 (erwachte Monsterform): teleportiert ständig und ruft unverwundbare Schattendämonen — nur in seinen Stillstand-Momenten angreifen, bei verschränkten Armen kommt sein Konter, immer seitlich statt rückwärts ausweichen. Vorher Damianes Start-Rüstung 1–2 Stufen upgraden und 100+ Grilled Meat mitnehmen; langer Geduldskampf.","conf":"medium"}],"boss":"Lucian Bastier (Damiane-Solo) + Gabriel Caliburn (scripted Loss)","warn":"'Words Left by the Riverside' & 'Strength Held in the Fingertips' sind Greymanes-Fraktionsquests zu Kap.-8-Beginn (keine Hauptquests, laut Quellen NICHT verpassbar); Oongka ist während Letzterer nicht spielbar."},
  {"ch":"9","name":"The Sage of the Desert","quests":[{"q":"An Unknown Voice","trigger":"Südlich von Demeniss: mit den Hexen (Maegu und Woosa) oben auf der Klippe sprechen","prereq":"A Fleeting Dream (Abschluss Kapitel 8)","reward":"—","miss":false,"tip":"Neben den Hexen hergehen (Taste gedrückt halten, um Schritt zu halten); nach der Cutscene setzen sie einen am Höhleneingang bei Crookstone Crag ab. Durch Höhle und Canyon dem Marker folgen – nur schwache Gegner. An der goldenen Statue startet per Cutscene die nächste Quest.","conf":"high"},{"q":"Cloister of Enlightenment","trigger":"Startet direkt nach An Unknown Voice an der goldenen Statue im Cloister (Crimson Desert)","prereq":"An Unknown Voice","reward":"—","miss":false,"tip":"Einziges Ziel: die markierte goldene Statue mit dem neuen Angriff Focused Force Palm reinigen. Auf den Oberkörper der Statue springen, Focus aktivieren, die Attacke aufladen und die golden leuchtende Kugel in der Statuenmitte treffen. Danach verzweigt das Kapitel über vier Steintafel-Rätsel in vier Stränge.","conf":"high"},{"q":"Mark of the Scar","trigger":"Im Cloister of Enlightenment eine der vier goldenen Tafeln vor den Statuen untersuchen (Rätsel heranzoomen)","prereq":"Cloister of Enlightenment","reward":"Skills Back Hang und Aerial Maneuver","miss":false,"tip":"Das Tafel-Rätsel markiert den Berg Urdavah im Norden. Den Berg erklimmen – in der Luft bis zu dreimal Force Palm einsetzen, um sich nach oben zu boosten. Am Schnellreisepunkt auf dem Gipfel startet eine Cutscene mit einem verwundeten Drachen, dem ein Speer im Rücken steckt.","conf":"high"},{"q":"Shackles of Fate","trigger":"Questmarker auf der Brücke am Great Gate of Urdavah (game8: World's Navel); per 'Wait'-Aktion das Eintreffen des Drachen auslösen","prereq":"Mark of the Scar","reward":"Stardust Necklace (Accessoire), Knowledge: Blackstar, Region Great Gate of Urdavah befreit","miss":false,"tip":"Zum Drachen Blackstar gleiten, mit Axiom Force andocken und aufsitzen. Rund zwei Minuten festhalten; die Widerstands-Aktion nur bei wildem Schütteln nutzen, um Stamina zu sparen. Dann mit Focused Force Palm die golden leuchtenden Stellen treffen, um die Verderbnis zu reinigen und die Speere zu entfernen. Misslungene Aufstiege lassen sich per 'Wait' beliebig wiederholen.","conf":"high"},{"q":"Crossing Point","trigger":"Im Cloister of Enlightenment die nächste goldene Tafel untersuchen (Rätsel: 'where the swords of past and present cross')","prereq":"Cloister of Enlightenment (Steintafel-Rätsel; im Hub nach Shackles of Fate gelistet)","reward":"—","miss":false,"tip":"Das Rätsel führt zum Spire of the Sun – laut PowerPyx in den Forebearer's Barrens, laut game8 im Valley of Grief (Quellenwiderspruch beim Regionsnamen). Einfach zum Turmeingang reisen; die Annäherung schließt die Quest automatisch ab.","conf":"medium"},{"q":"Unwavering Steps","trigger":"Startet direkt nach Crossing Point am Spire of the Sun","prereq":"Crossing Point","reward":"Witch's Ring (Accessoire), Greymane's Earring (Accessoire), Challenges 'Spire of the Sun' und 'Nest of Valor'","miss":false,"tip":"Drei Spiegel-Rätsel lösen, um den Lichtstrahl zum Abyss-Tor zu lenken: erst einen Eckspiegel versetzen, dann fünf Spiegel neu ausrichten, zuletzt die Spiegel etagenweise im Turm aktivieren und den Strahl auf den Deckenkristall richten. Danach Einzelduell gegen Goyen (Schwert und Schild) – er trifft extrem hart bis hin zum One-Shot; seiner Sprung-Schockwelle ausweichen und nur die Lücken nach seinen Angriffen nutzen.","conf":"high"},{"q":"Morning Fog","trigger":"Im Cloister of Enlightenment die goldene Tafel mit dem Rätsel vom südlichen Gipfel im Morgennebel untersuchen","prereq":"Cloister of Enlightenment (Steintafel-Rätsel; im Hub nach Unwavering Steps gelistet)","reward":"—","miss":false,"tip":"Das Rätsel zeigt auf die Insel Serpent Marsh südlich von Demeniss. Von Norden über die kleinen Inseln anreisen statt zu schwimmen (Stamina-Risiko). Am Questmarker schließt die Mission automatisch ab und die nächste beginnt.","conf":"high"},{"q":"Jijeong Temple in Chaos","trigger":"Serpent Marsh (South Demeniss): zum Tempelgipfel klettern und mit dem Kind-Mönch sprechen","prereq":"Morning Fog","reward":"—","miss":false,"tip":"Drei beschädigte Pensive Statues reparieren: je zwei Steinhände finden und mit Axiom Force ansetzen – der grüne Nebel zeigt die korrekte Ausrichtung an –, dann mit Force Palm aus dem passenden Winkel fixieren. Zur dritten Statue gelangt man per Gleitflug durch einen Höhlenabschnitt.","conf":"high"},{"q":"Path to Enlightenment","trigger":"Serpent Marsh: zurück zum Altar auf dem Berggipfel (Morning Mist Peaks) zum Mönchsjungen","prereq":"Jijeong Temple in Chaos","reward":"—","miss":false,"tip":"Reine Dialog-Quest: dem Mönch melden, dass die Pensive Statues restauriert sind. Der freigeschaltete Schnellreisepunkt am Tempel verkürzt den Anmarsch erheblich.","conf":"high"},{"q":"Path of the Disciple","trigger":"Serpent Marsh: drei Trainingsplätze des Tempels werden auf der Karte markiert","prereq":"Path to Enlightenment","reward":"3x Abyss Artifact","miss":false,"tip":"Drei Parkour-Trainingsplätze (Holztore hoch in den Bergen) in beliebiger Reihenfolge absolvieren – PowerPyx empfiehlt die Reihenfolge dritter, zweiter, erster. Innerhalb des Zeitlimits grüne Orbs einsammeln; die Limits sind großzügig (20–30 Sekunden Puffer). Sprünge per gezieltem Sprung ansetzen (blaue Landemarkierung) und auf Seilen den Sprint halten.","conf":"high"},{"q":"True Strength","trigger":"Serpent Marsh: Rückkehr zur ersten reparierten Pensive Statue löst automatisch Cutscene und Bosskampf aus","prereq":"Path of the Disciple","reward":"Wooden Mask of Lost Justice (Head Armor), Wanderer of Faith Leather Gloves (Glove Armor), T'rukan's Fighting Spirit, 1x Abyss Artifact","miss":false,"tip":"Bossduell gegen T'rukan the Ascended (Leopardenmaske, eine Lebensleiste): schnelle, extrem harte Fausthiebe, aber wenig HP. Auf mittlerer Distanz bleiben, nach seinen Angriffen nur 1–2 Treffer setzen und zurückweichen; bei Projektilen oder lila Aufglühen ausweichen, Blinding Flash stunnt ihn für einen Finisher. Nach dem Sieg das blaue Artefakt am Arena-Tor einsammeln, um die Quest zu beenden.","conf":"high"},{"q":"Face the Inner Self","trigger":"Serpent Marsh: das nun geöffnete Tor an der Pagode auf dem höchsten Gipfel (Jijeong Temple Pagoda)","prereq":"True Strength","reward":"—","miss":false,"tip":"Auf den Südwest-Berg zur Pagode klettern, das Abyss Gate aktivieren und in der gefluteten Höhle den rechten Weg nehmen; oben beendet eine Cutscene (Gespräch mit dem Jungen) die Quest. Schließt den Spire 'Jijeong Temple Pagoda' ab und öffnet den Zugang zum Abyss Ascetic's Rest samt Schnellreise; die Abyss-Reparatur selbst ist optional.","conf":"high"},{"q":"Fragments of Darkness","trigger":"Im Cloister of Enlightenment die letzte goldene Tafel untersuchen; danach im Turm in Nord-Demeniss (Tariv) mit dem sprechenden Gemälde reden","prereq":"Cloister of Enlightenment (Steintafel-Rätsel; im Hub nach Face the Inner Self gelistet)","reward":"—","miss":false,"tip":"Im Sanctum (game8: Sanctum of Mortification) Gegner räumen, den zerstörten Pylon mit Axiom Force reparieren, Ranken mit Concentrating Light wegbrennen und den Power-Core-Würfel im Kuku Pot versiegeln; den Reaktorkern anschließend im Hauptreaktorturm einsetzen. Geht der Kuku Pot verloren, gibt es Ersatz im Lost & Found des Howling Hill Greymane Camp oder per Dispatch-Mission 'Kuku Pot Production'.","conf":"high"},{"q":"Pursuit Beyond the Veil","trigger":"Demeniss > Hexe Sanctuary; startet nach Abschluss von Fragments of Darkness","prereq":"Fragments of Darkness","reward":"—","miss":false,"tip":"Vier Totems zerstören: Hollow Haven (Süden), Forgotten Tomb (Osten), Clay Urn Necropolis (Norden), Brimstone Springs (Westen) – PowerPyx empfiehlt, im Süden zu starten. Jeweils den Charged Shot des Bogens nutzen (kostet 1 Abyss Artifact). Gespawnte Gegner und die auftauchende Hexe Marie komplett ignorieren – sie ist hier nicht besiegbar und verschwindet von selbst; keine Heilmittel verschwenden.","conf":"high"},{"q":"Black Witch","trigger":"Startet automatisch am Hexe Sanctuary (Demeniss) nach Pursuit Beyond the Veil","prereq":"Pursuit Beyond the Veil","reward":"Earring of Dark Magic (Accessoire), Crow Whisperer (Two-Handed Weapon)","miss":false,"tip":"Bosskampf gegen Hexe Marie (zwei Lebensleisten): den Krähen-Projektilen seitlich ausweichen, beschworene Minions sofort umhauen (ein Treffer genügt) und in ihren Pausen schwere Kombos landen, bevor sie wegteleportiert. Aggressiv bleiben und Schaden eher tanken, statt allem auszuweichen – sonst zieht sich der Kampf endlos. In Phase 2 beschwört sie häufiger Minions.","conf":"high"},{"q":"The Cloister of Enlightenment","trigger":"Zurück im Cloister of Enlightenment, nachdem alle vier Tafel-Stränge (Shattered Ties, Thinning Blade, Six Pensive Statues, Veiled Witch) abgeschlossen sind","prereq":"Abschluss aller vorherigen Kapitel-9-Stränge (zuletzt Black Witch)","reward":"—","miss":false,"tip":"Drei Stat-Check-Tore aufdrücken (gegen das Tor laufen): laut PowerPyx Health Level 7, Stamina Level 6 und Spirit Level 6 – game8 nennt abweichend Health 6, Stamina 6, Spirit 5. Das Health-Tor entzieht beim Drücken laufend Leben, daher nur mit voller Leiste starten. Notfalls mit Faded Abyss Artifacts (Hexe in den Witchwoods bei Hernand) Skillpunkte umverteilen und danach zurücksetzen.","conf":"medium"},{"q":"The Sage of the Desert","trigger":"Direkt nach den drei Stat-Toren beim Betreten des nächsten Raums (Cutscene leitet den Bosskampf ein)","prereq":"The Cloister of Enlightenment","reward":"—","miss":false,"tip":"Zwei-Phasen-Duell gegen Master Du: In Phase 1 seine Nahkampfangriffe parieren, um ihn zu staggern, dann schwere Treffer nachlegen; den Säulensprung-Attacken ausweichen. Phase 2 bringt grüne Laserangriffe, die perfekte Dodges erfordern. Palmer Pills als Wiederbelebung mitnehmen, besonders mit wenig Health-Upgrades.","conf":"high"},{"q":"New Perspectives","trigger":"Startet nach The Sage of the Desert am Spire of the Sun","prereq":"The Sage of the Desert","reward":"Karmic Pulse (Abyss Gear) – nur von PowerPyx gelistet; game8 nennt keine Belohnung","miss":false,"tip":"Im obersten Stockwerk des Spire of the Sun durch das Abyss-Portal zum Nest of Valor; die Skybridge aktivieren, indem man die Säule mit Axiom Force dreht, bis sie blau leuchtet. Über Teleporter und bewegliche Steintore weiter, dann den großen schwebenden Fels mit dreimal Force Palm in der Luft (an den Rastpunkten) erklimmen. Oben wartet Master Du am Throne of Truth zur Abschluss-Cutscene; das optionale Throne-of-Truth-Abyss-Puzzle lässt sich überspringen.","conf":"medium"},{"q":"Lust for Power","trigger":"Rückkehr zum Greymane-Lager auf Howling Hill; Gefährten am schwarzen Zelt ansprechen","prereq":"New Perspectives","reward":"—","miss":false,"tip":"Minimal-Quest mit einem einzigen Cutscene-Ziel: im Lager mit den am schwarzen Zelt versammelten Gefährten (laut game8 die Greymanes und Damiane) interagieren. Die verbündeten Fraktionen sammeln sich für den Gegenangriff bei Fort Musket; damit endet Kapitel 9 sofort.","conf":"high"}],"boss":"T'rukan the Ascended + Hexe Marie + Master Du"},
  {"ch":"10","name":"Counterattack","quests":[{"q":"Untouchable","trigger":"Am Outpost in der Region Delesyia > Gorthak (game8: Musket First Outpost)","prereq":"Lust for Power (letzte Quest Kapitel 9)","reward":"—","miss":false,"tip":"Reine Story-Quest ohne Kampf: Zum Questmarker reiten und am großen weißen Zelt die Zwischensequenz auslösen ('Rally at the Outpost'). Die verbündeten Fraktionen planen den Gegenschlag gegen Caliburn und die fliegende Festung über Fort Musket.","conf":"high"},{"q":"The Gate of War","trigger":"Delesyia > Gorthak — Steinturm am Questmarker (Gate of Peace)","prereq":"Untouchable","reward":"—","miss":false,"tip":"Zum Gate of Peace laufen — an den mechanischen Insekten kann man vorbeirennen — und den Turm bis ganz oben hochsteigen. Rechts am Zahnrad den Disruptor einsetzen, dann den großen Hebel in der Mitte ziehen. Danach unten auf der Festungsmauer mit dem Orc Captain sprechen.","conf":"high"},{"q":"Master of the Ironworks","trigger":"Delesyia > Gorthak — Questmarker im Zentrum Gorthaks","prereq":"The Gate of War","reward":"—","miss":false,"tip":"Zum Marker reiten; die gegen Orcs kämpfenden Mech-Insekten kann man ignorieren und einfach passieren. Nach der Cutscene Valgash, dem Anführer Gorthaks, den Hügel hinab folgen, bis die nächste Sequenz die Quest abschließt. Kein Kampf nötig.","conf":"high"},{"q":"Hidden Ace","trigger":"Delesyia > Gorthak — beim Zwerg (game8: Marek) vor dem blauen Roboter, nahe dem Ende der Vorquest","prereq":"Master of the Ironworks","reward":"—","miss":false,"tip":"Tutorial für das Mech-Reittier A.T.A.G. (Raketen + Gatling Gun). Auf dem Übungsgelände in den Ruinen unterhalb 15 beliebige Ziele zerstören — am einfachsten mit der Schnellfeuerwaffe. Zurück zum Zwerg, dem Artisan-Orc folgen, dann rechts am Tor den Hebel ziehen und den A.T.A.G. hinter dem geöffneten Tor besteigen.","conf":"high"},{"q":"Clockwork Insect Clash","trigger":"Delesyia > Gorthak — rot markierter Bereich auf der Karte","prereq":"Hidden Ace","reward":"—","miss":false,"tip":"Mechanische Insekten im markierten Gebiet eliminieren, bis der Gegner-Zähler auf 0 % fällt (dauert einige Minuten). Den A.T.A.G. nutzen, bis er zerstört wird, danach zu Fuß weiterkämpfen — laut game8 gibt es Repair-Sites und Ersatz-Mechs in der Nähe.","conf":"high"},{"q":"Beating Heart","trigger":"Delesyia > Gorthak — Kraftwerksgebäude (game8: Power Plant in Regent's Rise)","prereq":"Clockwork Insect Clash","reward":"—","miss":false,"tip":"Im Erdgeschoss das Thermalkraftwerk aktivieren: Hebel links ziehen, mit der Laterne den markierten Würfel unten rechts an der Maschine anleuchten und treten, dann den freigegebenen Hebel mehrere Sekunden halten, um das Gas zu zünden. Anschließend Valgash hinauf auf die Festungsmauer folgen. Widerspruch: game8 zählt die 3-Minuten-Verteidigung des Generators noch zu dieser Quest, PowerPyx erst zu 'Invaders from the East'.","conf":"medium"},{"q":"Invaders from the East","trigger":"Delesyia > Gorthak — Hangar nahe dem Kraftwerk, Hebel rechts am grün beleuchteten Tor öffnet den A.T.A.G.-Zugang","prereq":"Beating Heart","reward":"—","miss":false,"tip":"Im A.T.A.G. den Generator 180 Sekunden gegen Insektenwellen verteidigen: ohne Zoom mit der Gatling Gun schießen (leichtes Auto-Aim) und keinesfalls den Reaktor treffen; die Ballons mit Minen in der letzten Welle per Rakete abschießen (One-Hit). Danach an der großen Rail Gun das Rad links bedienen und zwei Sky Galleons mit je einem Schuss zerstören. Widerspruch: game8 ordnet die Verteidigungsphase der Vorquest 'Beating Heart' zu.","conf":"medium"},{"q":"Frozen Hearted Predator","trigger":"Delesyia > Gorthak — Questmarker nördlich von Gorthak (Absturzstelle)","prereq":"Invaders from the East","reward":"—","miss":false,"tip":"Bosskampf gegen Marni's Clockwork Mantis (eine Lebensleiste, wird zu Fuß bestritten). Gefährlichster Angriff sind die gelben Lasersalven — seitlich im Kreis um den Boss ausweichen. Nahkampfkombos dodgen, sich hinter den Boss positionieren und schwere Angriffe setzen (PowerPyx empfiehlt Tauria Curved Sword mit Nature's Echo). Ausweichen ist sicherer als Parieren, da viele Angriffe nicht parierbar sind; laut game8 verteidigt der Boss keine Angriffe.","conf":"high"},{"q":"Lingering Shadow","trigger":"Delesyia > Gorthak — Valgash bei Krall Foundry, neben seinem Pferd vor einem dunklen Zelt","prereq":"Frozen Hearted Predator","reward":"1x Abyss Artifact, Leofric Musket (Ranged Weapon) — laut PowerPyx; game8 nennt keine Belohnung","miss":false,"tip":"Mit Valgash sprechen, mit ihm die Straße hinaufreiten und gemeinsam durch das Lager gehen, bis die Abschluss-Cutscene ausgelöst wird. Beendet Kapitel 10 und leitet nach Kapitel 11 über — die direkte Konfrontation mit Marni in Delesyia ist nun die einzige Option.","conf":"medium"}],"boss":"Marni's Clockwork Mantis"},
  {"ch":"11","name":"Truth and Reality","quests":[{"q":"The City of Steel","trigger":"Startet automatisch nach Kapitel 10; Ziel ist Delesyia Castle im Osten der Region Delesyia","prereq":"Lingering Shadow (Kapitel 10)","reward":"—","miss":false,"tip":"Das Visione Helmet (der goldene Helm für Memory Fragments) aus dem Inventar aufsetzen — dann lassen die Castle-Wachen einen passieren. Den Weg hinauf und durch den Garten zum Haupttor des Castle folgen; eine Cutscene beendet die Quest. Kein Kampf.","conf":"high"},{"q":"Crossroads","trigger":"Beginnt gefangen im Kerker (Dungeon) von Delesyia Castle","prereq":"The City of Steel","reward":"—","miss":false,"tip":"Hebel ziehen, dann mit dem Visione Helmet am Zahnrad das Uhren-Puzzle lösen: Minuten- und Stundenzeiger müssen gleichzeitig blau leuchten (beide Tasten zugleich halten). Nach Memory Fragment und Hologramm im Visione-Modus durch die geöffnete Wand gehen, den Modus verlassen, die Tür öffnen und in die Teleport-Maschine steigen — Cutscene beendet die Quest.","conf":"high"},{"q":"Strange Manor","trigger":"Im Osten von Delesyia beim Manor mit der goldenen Statue am Eingang (Treffen mit dem mysteriösen Mann)","prereq":"Crossroads","reward":"—","miss":false,"tip":"Im Manor ein Gemälde abnehmen — dahinter steckt ein verstecktes Zahnrad. Mit dem Visione Helmet erneut das Zeiger-Puzzle lösen (beide Zeiger gleichzeitig blau) und das Memory Fragment ansehen. Danach durch abwechselnd nur im Visione- bzw. Realmodus sichtbare Türen navigieren, die Eingabegeräte aktivieren und am Transporter eines von drei Zielen wählen — dort beginnt die Schlüsselsuche der Folgequest.","conf":"high"},{"q":"Fortress Keys","trigger":"Geht im Transporter-Raum des Strange Manor automatisch (ohne Cutscene) aus der Vorquest hervor","prereq":"Strange Manor","reward":"Keine direkte Quest-Belohnung; jeder der drei Festungs-Bosse lässt 1 Artifact fallen (PowerPyx)","miss":false,"tip":"Per Transporter drei Orte abklappern und je einen Fortress Key aus den markierten Kisten holen: Valvegard Garrison (Boss Thunder Tank; game8 nennt ihn 'Thunder Crusher'), Aeronautical Research Base (Storm Crusher) und Marni's Laboratorium (Dreadnought). PowerPyx empfiehlt vorab Nature's Snare Lv. 2 und das Reflektieren der Tank-Projektile als Cheese-Methode; laut game8 lassen sich manche Bosskämpfe beim reinen Key-Einsammeln auch umgehen.","conf":"medium"},{"q":"Truth and Lies","trigger":"Im Strange Manor in Delesyia, direkt nach Abschluss der Vorquest","prereq":"Fortress Keys","reward":"—","miss":false,"tip":"Die 3 Fortress Keys in die Transporter-Maschine einsetzen und als Ziel Marni's Hideout wählen (PowerPyx schreibt teils 'Mani's Hideout'). Dort den Knopf an der Rückseite der großen Maschine drücken — die Wahrheit über das Wesen wird enthüllt. Im Versteck liegen zusätzlich Memory Fragment, Blueprint und ein Buch zum Einsammeln.","conf":"high"},{"q":"Master of a Forgotten Land","trigger":"Startet in Delesyia automatisch nach der Vorquest; laut game8 zunächst Golden Star's Power Core in Marni's Masterium holen","prereq":"Truth and Lies","reward":"Golden Fire","miss":false,"tip":"Bosskampf gegen Golden Star, einen großen goldenen Metall-Drachen (eine Lebensleiste, keine Phasen). Die aufgeladene Marni Disruptor Special Ammunition bzw. Speere aus den blau leuchtenden Generatoren der Arena auf ihn werfen — füllt schnell die Stagger-Leiste. Hängt der Drache an der rechten Wand, hochklettern und die exponierte Klaue attackieren, dabei den Feuerangriffen ausweichen; nach genug Schaden stürzt er betäubt zu Boden. Muster wiederholen bis zum Sieg, danach Cutscene mit White Crow.","conf":"high"},{"q":"Whispers in the Wind","trigger":"Startet direkt nach dem Golden-Star-Sieg per Cutscene in Delesyia (Nest of Valor)","prereq":"Master of a Forgotten Land","reward":"Blackstar als permanentes Drachen-Flugmount","miss":false,"tip":"Reine Cutscene-Quest ohne Kampf: White Crow erklärt, dass Blackstar als Transportmittel zur unerreichbaren fliegenden Festung dient. In den Abyss hinabfallen und auf Blackstars Rücken landen — Quest sofort abgeschlossen. Das Drachen-Mount ist danach jederzeit über das Charakter-Auswahlrad rufbar.","conf":"high"},{"q":"Cloud Fortress Orbian","trigger":"Startet in Delesyia automatisch nach der Vorquest — man sitzt direkt auf dem fliegenden Drachen (game8 nennt die Quest 'Flying Fortress Orbian')","prereq":"Whispers in the Wind","reward":"—","miss":false,"tip":"Im Drachenflug die Energiequellen rund um die Festung zerstören (PowerPyx: 5 gelbe Kerne, game8: 6 Ringe), dann per Stab-Skill einen Pfeiler drehen und über die offene Luke mit Force Palm eindringen. Innen die grünen Glasbarrieren zerstören, über Kabel aufs Dach klettern, das zentrale Gerät anstechen und durch das Nordtor (Focused Force Palm am rotierenden Tor) zum Kern-Boss — game8 nennt ihn H.A.L.L., PowerPyx beschreibt ihn als goldenes Auge; Laser per Bogen oder Nature's Snare im Focus-Modus kontern. WICHTIG: Im Bosskampf nicht sterben (Palmer Pill mitnehmen), sonst Respawn am Festungsanfang und alle Schritte müssen wiederholt werden. Kein Point of No Return — danach folgt regulär Kapitel 12.","conf":"medium"}],"boss":"Golden Star","warn":"Kein Point of No Return — nach dem Finale (Kap. 12) bleibt Free-Roam, Hauptquests sind generell nicht wiederholbar. In Orbian im Bosskampf nicht sterben (Palmer Pill mitnehmen), sonst Respawn am Festungsanfang."},
  {"ch":"12","name":"The Abyss","quests":[{"q":"Precise Execution","trigger":"Am Outpost von Fort Musket — Stefan Lanford am Questmarker ansprechen (automatische Cutscene)","prereq":"Cloud Fortress Orbian (Kapitel 11)","reward":"—","miss":false,"tip":"Sehr kurze Planungs-Quest ohne Kampf: Nach der Zerstörung der Flying Fortress Orbian zum Outpost zurückkehren und Stefan Lanford ansprechen, um den Angriff auf Fort Musket zu planen. Die Cutscene startet direkt die nächste Quest.","conf":"high"},{"q":"Deferred Advance","trigger":"Startet automatisch nach Precise Execution — Drachensequenz über dem Schlachtfeld vor Fort Musket","prereq":"Precise Execution","reward":"—","miss":false,"tip":"Laut PowerPyx eine der schwersten Quests des Spiels: Auf dem Drachen drei große Kanonen zerstören; die Drachen-HP ist nicht heilbar, fällt sie auf ~5 %, schlägt die Quest fehl und muss neu gestartet werden. Zuerst alle Blimps ausschalten (höchster Schaden), dann die Kanonen (PowerPyx-Reihenfolge: rechts, Mitte, links; game8 rät, nicht mit der mittleren zu beginnen). Tief am Boden unterhalb der Kanonenberge fliegen, um außer Reichweite zu bleiben, und zwischendurch landen, damit sich die Stamina regeneriert.","conf":"high"},{"q":"Departure of the Brave","trigger":"Startet automatisch nach Deferred Advance — Abschiedszeremonie im Hof des Outposts","prereq":"Deferred Advance","reward":"—","miss":false,"tip":"An der Zeremonie teilnehmen, die Treppe hinauf zu den Gefährten am Hügel (Cutscene) und auf das Angriffssignal warten. Am Rear Gate von Fort Musket wartet ein großer Schildträger (game8: Righteous Inquisitors Commander) — kleinere Gegner ignorieren. Perfekt getimte Schild-Paraden unterbrechen ihn und öffnen Combo-Fenster; rund 10 volle Combos nötig, also Heilung mitnehmen (ca. 20 Grilled Meat).","conf":"high"},{"q":"Forbidden Gate","trigger":"Startet automatisch nach dem Sieg über den Schildträger vor Fort Musket","prereq":"Departure of the Brave","reward":"—","miss":false,"tip":"Einfach zum Questmarker am höchsten Punkt von Fort Musket laufen — alle Gegner lassen sich komplett ignorieren. Oben löst eine Cutscene mit Caliburn aus, der in den Abyss flieht. WICHTIG: Spätestens jetzt manuell speichern und Vorräte auffüllen (200+ Grilled Meat, 5+ Palmer Pills), bevor es durch das Abyss-Tor geht.","conf":"high"},{"q":"A Shadow in the Void","trigger":"Startet automatisch nach Forbidden Gate — Verfolgung Caliburns in den Abyss","prereq":"Forbidden Gate","reward":"Twisted Verdict (Weapon – Two-Handed Sword)","miss":false,"tip":"Im Abyss die Rätsel lösen, v. a. am Monolith Crown (PowerPyx-Sequenz: UP, UP, UP, LEFT, LEFT, UP (schnell), UP; game8: erst die beiden Laser rechts ausrichten), dann über die Crescent Skybridge zu den Dimensional Bonds. Dort wartet Corrupted Caliburn (3 Phasen, beschwört Schattenkopien): hinter ihn dodgen, schwere Combo plus leichte Treffer, dann den Schattenwellen ausweichen — gefährlichster Angriff ist sein Sprung-Schwertschlag; Skills können ihn unterbrechen. Vorher manuell speichern: Wer nach dem ersten Boss beendet, muss den Encounter wiederholen.","conf":"high"},{"q":"Blinding Darkness","trigger":"Startet automatisch nach A Shadow in the Void — durch das Abyss Gate hinter Corrupted Caliburn","prereq":"A Shadow in the Void","reward":"—","miss":false,"tip":"Doppelter Endkampf: Erst Avatar of Umbra (Myurdin) — laut PowerPyx 2 Phasen mit zwei Lebensbalken, laut game8 3 Phasen in einer heißen Arena (Fire Resistance hilft); hinter den Boss dodgen, Magieangriffe nicht parieren, rote Laser mit Nature's Snare reflektieren. Danach Umbra als finaler Luftkampf auf dem Drachen: Feuerbälle aufs Auge, bis die Stun-Leiste voll ist, dann abspringen, hingleiten und mit Force Palm zuschlagen (2–3 Treffer). NIEMALS die 'Give-Up'-Option wählen oder das Spiel schließen — man spawnt sonst weit entfernt und das Tor zu Corrupted Caliburn ist nicht erneut betretbar; nur ein manueller Save von davor rettet. Nach dem Sieg folgen Abspann und der Epilog.","conf":"high"}],"boss":"Corrupted Caliburn → Avatar of Umbra → Umbra","warn":"Vor dem Abyss-Tor (Ende 'Forbidden Gate') manuell speichern und Vorräte auffüllen (200+ Grilled Meat, 5+ Palmer Pills). Im Finale niemals 'Give Up' wählen oder das Spiel schließen — sonst Aussperrung vom Bosskampf; nur der manuelle Save davor rettet."},
  {"ch":"Epilog","name":"Journey's End","quests":[{"q":"A New Beginning","trigger":"Startet automatisch nach Blinding Darkness — man spawnt mit Oongka in Pailune","prereq":"Blinding Darkness","reward":"Gold-Trophäe/Achievement 'Expert Storyteller' (Story-Abschluss)","miss":false,"tip":"Mit Oongka vom Spawnpunkt zu den Docks von Pailune laufen; dort schließt die Quest automatisch ab und markiert das offizielle Story-Ende. Danach öffnet sich das Post-Game-Free-Roam: Die restlichen 7 Epilog-Dialogquests sind in beliebiger Reihenfolge machbar.","conf":"medium"},{"q":"Peace in Hernand","trigger":"Hernand (Stadt) — Marshal Middler auf der Straße im Westen der Stadt ansprechen","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Kurze Dialog-Quest: Nach Hernand reisen und Marshal Middler im Westen der Stadt ansprechen — er erzählt, dass er zum Baron ernannt wurde. Damit ist die Quest bereits abgeschlossen.","conf":"medium"},{"q":"The Unyielding Shields","trigger":"Calphade Castle (Nord-Hernand) — Stefan Lanford in seinem Büro im obersten Stockwerk","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Durch das Haupttor von Calphade Castle, vom Thronsaal nach rechts und die Treppe hinauf zu Stefans Büro. Die Cutscene — Stefan plant eine Übung zur Friedenssicherung — beendet die Quest.","conf":"medium"},{"q":"The Heart of Pywel","trigger":"Demeniss — Villa nordwestlich der Stadt, Countess Colette Azerian (Frau im gelben Kleid) ansprechen","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Nach Caliburns Fall ist Demeniss feindfrei. Countess Azerian an der Villa nordwestlich der Stadt ansprechen und sie zurück Richtung Stadt begleiten; ein kurzer Dialog beendet die Quest.","conf":"medium"},{"q":"The Enduring Flame","trigger":"Gorthak (Region Delesyia) — Valgash am Questmarker bei den Gorthak Ironworks ansprechen","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Zu den Gorthak Ironworks reisen und mit Valgash über den Wiederaufbau nach dem Krieg sprechen (A.T.A.G. und Marni kommen zur Sprache). Der Dialog schließt die Quest ab.","conf":"medium"},{"q":"Evolving City","trigger":"Delesyia (Hauptstadt) — mit aufgesetztem Visione Helmet zum Burgtor gehen","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Mit dem Visione Helmet am Burgtor von Delesyia Einlass erhalten. Drinnen im Rüstungsmenü das Visione Helmet auswählen und unter Recollections im Tab 'Delesyia' die Erinnerung 'Visione' (erster Eintrag) ansehen — eine Aufzeichnung von Marni spielt ab und beendet die Quest.","conf":"medium"},{"q":"The Desert's Edge","trigger":"Fort Musket (Region Crimson Desert) — Duke Wells bei den im Kreis stehenden Soldaten im Hof","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Nach Süden zum Fort Musket reisen und sich der Soldatenversammlung im Hof nähern. Die Cutscene mit Duke Wells über Wiederaufbau und künftige Besatzung des Forts beendet die Quest.","conf":"medium"},{"q":"New Horizons","trigger":"Varnia (Nordrand der Crimson-Desert-Region) — den zwei Männern auf einem Turm nähern (Wiedersehen mit Sebastian)","prereq":"A New Beginning","reward":"—","miss":false,"tip":"Nach Varnia reisen und sich den zwei Männern auf dem Turm nähern — die automatische Cutscene mit Sebastian beendet die Quest. Laut PowerPyx ist dies die 168. und letzte Hauptmission des Spiels.","conf":"medium"}]},
];
